/* Java 初级课程正文注册表（由 frag-beg 碎片自动生成）。
   合并扩展已有 QZ_CONTENT（中级/高级），不覆盖；key = track|stack|lessonName。 */
window.QZ_CONTENT = (function (prev) {
  'use strict';
  var data = {
    "backend|java|认识后端：第一个能跑的服务": { "body": "<p class=\"lead\">新手村第一课：搞懂后端在产品里站什么位置、.java 到跑起来的服务中间经过什么、JDK/IDEA/Maven 各管哪段，再亲手跑起第一个 Maven 项目。不急着敲代码，先把地基想清楚。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">分工</span><span class=\"s\">三层各管一段</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">跑起来</span><span class=\"s\">源码→JVM</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">环境</span><span class=\"s\">JDK/IDEA/Maven</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>按按钮掉饮料：中间那四件事归你写</h2>\n    <p>先讲个故事。你按自动售货机按钮，饮料掉下来。中间其实四件事：认出你按哪格、查还有没有货、扣钱、把货推出来。<b>写后端就是写中间这四件事</b>——前端负责按钮和屏幕，数据库负责记住还剩几瓶，中间的判断归你。</p>\n    <p>手机登录也一样：App 发账号密码→后端验身份查库→库返回用户信息→后端返回登录成功+Token→App 跳首页。不管网页/App/桌面，套路都一样，区别只在<b>谁负责哪一块</b>。把扣钱逻辑写进按钮里，机器就乱了。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>前端管看得见的，后端管判断和记账，数据库管记住；谁也别抢谁的活。</div>\n    <div class=\"recap\"><b>收束：</b>后端=中间判断层；一次点击=请求→判断/查库→响应。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>三层分工：展示收集 / 判断记账 / 记住</h2>\n    <p><b>前端</b>干三件事：展示(渲染列表头像图表)、收集(表单点击手势)、美化(布局配色动画)。它不存数据也不做核心判断。<b>后端</b>干三件事：校验(身份/参数/权限)、业务判断(扣钱/扣库存/路由)、编排(查库/调外部/组装响应)。<b>数据库</b>只干一件事：可靠地记住和取回。</p>\n    <p>为什么不能混？把判断放前端=用户改改页面就绕过扣钱；把展示放后端=每改个配色都要重发服务。分层让每层只干自己的活，出错时也知道<b>看哪一层</b>：界面错看前端、逻辑错看后端、数据错看库。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"一次登录请求的三层流转\">\n        <defs><marker id=\"arb1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"200\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"108\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">前端 App/网页</text><text x=\"108\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">展示+收集: 账号密码</text>\n        <rect x=\"280\" y=\"26\" width=\"200\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"380\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">后端服务</text><text x=\"380\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">验身份+判断+组装响应</text>\n        <rect x=\"552\" y=\"26\" width=\"200\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"652\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">数据库</text><text x=\"652\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">记住/取回用户数据</text>\n        <line x1=\"208\" y1=\"44\" x2=\"278\" y2=\"44\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb1)\"/>\n        <line x1=\"480\" y1=\"44\" x2=\"550\" y2=\"44\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb1)\"/>\n        <line x1=\"550\" y1=\"66\" x2=\"482\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb1)\"/>\n        <line x1=\"278\" y1=\"66\" x2=\"210\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb1)\"/>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">请求→判断/查库→响应；界面错看前端、逻辑错看后端、数据错看库</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">把扣钱写进按钮=用户改页面就绕过；分层让每层只干自己的活</text>\n      </svg>\n      <figcaption>图 1 · 一次登录：前端送操作、后端做判断、数据库记住。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>分层=各管一段+出错知道看哪层；核心判断永远在后端。</div>\n    <div class=\"recap\"><b>收束：</b>前端展示收集/后端校验判断编排/数据库记住取回。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>源码→字节码→JVM→JAR→服务进程</h2>\n    <p>你写的 <span class=\"term\">.java</span> 是人看的源码，机器不直接懂。<b>编译</b>(javac/Maven)把它变成 <span class=\"term\">.class 字节码</span>；<span class=\"term2\">JVM</span> 读字节码逐条解释/ JIT 编译成机器码执行。把一堆 .class+资源打成一个 <span class=\"term\">JAR</span> 包，用 <code>java -jar</code> 启动就是一个<b>服务进程</b>，蹲在服务器上监听端口等请求。</p>\n    <p>所以「跑不起来」要分段查：编译报错=源码/依赖问题；编译过但启动报错=JVM/配置/端口问题；启动过但请求错=业务逻辑问题。<b>知道在哪一段</b>就不乱猜。字节码「一次编译到处运行」靠的是各平台各自的 JVM。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>.java→(编译).class→(JVM)执行→(打包)JAR→(java -jar)服务进程；跑不起来先定位在哪一段。</div>\n    <div class=\"recap\"><b>收束：</b>源码/字节码/JVM/JAR/进程五段；跨平台靠各平台 JVM。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>JDK/IDEA/Maven 各管哪段，别装错配错</h2>\n    <p><span class=\"term\">JDK</span>=开发工具包：含编译器 javac+运行时 JRE+类库，是「能编译能跑」的根本。<span class=\"term2\">IDEA</span>=编辑器+调试器：写代码/断点/看变量，它本身不编译运行，而是调用 JDK。<span class=\"term\">Maven</span>=依赖+构建管家：按 pom.xml 下载依赖、编译、打包、跑测试。</p>\n    <p>常见坑：IDEA 里配的 JDK 和命令行 JAVA_HOME 不是同一个→「IDE 能跑命令行不能」；Maven 镜像没配→依赖下载慢/失败；JDK 版本和项目要求不符→编译报错。<b>三者配对</b>：同一 JDK 版本、IDE 指向它、Maven 用它编译。装完用 <code>java -version</code>/<code>mvn -version</code> 核对。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>JDK 管编译运行、IDEA 管写和调、Maven 管依赖和构建；三者指向同一 JDK 才不折磨。</div>\n    <div class=\"recap\"><b>收束：</b>JDK/IDEA/Maven 分工+版本配对+java -version/mvn -version 核对。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>第一个 Maven 项目：建、跑、断点盯变量</h2>\n    <p>建项目：<code>mvn archetype:generate</code> 或 IDEA 新建 Maven 项目→得到 pom.xml+src/main/java。写一个主类带 <code>main</code> 方法→<code>mvn compile</code> 编译→<code>mvn exec:java</code> 或 IDE 运行→控制台看到输出=跑起来了。</p>\n    <p>再学<b>断点</b>：在可疑行点一下→Debug 运行→程序停在那→看变量当前值→单步走一行看变化。断点把「猜」变成「看」。过关标准：不抄命令也能自建 Maven 项目、命令行和 IDE 都能跑、能断点盯变量、能顺溜讲清源码到运行全过程。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>建→编译→运行→断点四步；断点把猜变成看；能讲清全过程才算过关。</div>\n    <div class=\"recap\"><b>收束：</b>Maven 项目结构+compile/运行+Debug 断点单步+讲清五段链。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：三层分工、跑起来 checklist</h2>\n    <p>演练一看「把扣钱写进按钮」和「三层各司其职」的差别。演练二勾选跑起来的四个条件，看服务能否启动、报错落在哪一段。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种分工</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"mix\" class=\"on\">❌ 逻辑写进按钮</button><button data-k=\"layer\">✅ 三层各司其职</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一台售货机，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 跑起来 checklist</b><span class=\"hint\">勾选四个条件</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1jdk\" checked> JDK 装对且版本匹配</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1dep\" checked> Maven 依赖下载齐</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1comp\" checked> 编译通过(.class)</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1main\" checked> 主类/端口配置正确</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">缺哪条→报错落在哪一段；全齐→服务进程监听端口</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>逻辑放前端=改页面就绕过扣钱；跑不起来先分段：JDK/依赖=环境段、编译=源码段、主类端口=启动段。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经知道后端管什么、代码怎么跑起来。下一课把 Java 本身摸熟。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>后端职责</td><td>售货机中间四件事</td><td>校验/判断/编排</td></tr>\n      <tr><td>三层分工</td><td>按钮/判断/库存表</td><td>前端展示/后端判断/库记住</td></tr>\n      <tr><td>编译运行链</td><td>.java→.class→JVM</td><td>JAR→java -jar→进程</td></tr>\n      <tr><td>JDK</td><td>编译+运行根本</td><td>javac+JRE+类库</td></tr>\n      <tr><td>IDEA</td><td>写和调</td><td>调用 JDK, 本身不编译</td></tr>\n      <tr><td>Maven</td><td>依赖+构建管家</td><td>pom.xml/compile/package</td></tr>\n      <tr><td>断点</td><td>把猜变成看</td><td>停行/看变量/单步</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，命令为示例；沙盒为启发式判定。口径以初级 README 与第一篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第一篇-认识Java后端 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 毕业项目与过关标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://dev.java/learn/\" target=\"_blank\" rel=\"noopener\">Dev.java Learn</a> <span class=\"src\">— Java 入门与运行原理</span></li>\n        <li><a href=\"https://maven.apache.org/guides/getting-started/\" target=\"_blank\" rel=\"noopener\">Maven Getting Started</a> <span class=\"src\">— 第一个 Maven 项目</span></li>\n        <li><a href=\"https://spring.io/quickstart\" target=\"_blank\" rel=\"noopener\">Spring Quickstart</a> <span class=\"src\">— 后续 Spring Boot 入口</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://dev.java/learn/\" target=\"_blank\" rel=\"noopener\">Dev.java 语言基础</a> <span class=\"src\">— B2 面向对象/集合/并发</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"售货机分工"},{"id":"b","title":"三层各管一段"},{"id":"c","title":"源码到进程"},{"id":"d","title":"JDK/IDEA/Maven"},{"id":"e","title":"第一个项目"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var MIX=\"// ❌ 扣钱逻辑写进按钮(前端)\\n用户改改页面 → 绕过扣钱\\n每改配色都要重发服务\\n界面错/逻辑错/数据错 混在一起\\n出错不知道看哪一层\";\n  var LAYER=\"// ✅ 三层各司其职\\n前端: 展示+收集(按钮/屏幕)\\n后端: 校验+判断+编排(扣钱/查库存)\\n数据库: 记住/取回(库存表)\\n界面错看前端 / 逻辑错看后端 / 数据错看库\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"mix\"?MIX:LAYER);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"mix\"?\"err\":\"ok\")+\"\\\">\"+(k===\"mix\"?\"改页面就绕过+出错无处查\":\"各管一段+出错知道看哪层\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"mix\"?\"谁抢谁的活机器就乱\":\"核心判断永远在后端\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"mix\");\n})();\n\n// 演练二：跑起来 checklist\n(function(){\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var jdk=chk('g1jdk'), dep=chk('g1dep'), comp=chk('g1comp'), main=chk('g1main');\n    var stage = !jdk? '环境段: JDK' : (!dep? '环境段: 依赖' : (!comp? '源码段: 编译' : (!main? '启动段: 主类/端口' : '运行中')));\n    var ok = jdk&&dep&&comp&&main;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(ok?'good':'bad')+'\"><b>'+(ok?'跑起来':'跑不起')+'</b><small>服务状态</small></div>'+\n      '<div class=\"stat-box\"><b>'+stage+'</b><small>报错/状态段</small></div>'+\n      '<div class=\"stat-box\"><b>'+([jdk,dep,comp,main].filter(Boolean).length)+'/4</b><small>条件齐备</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(jdk?'on':'bad')+'\">JDK '+(jdk?'对':'错/缺')+'</span>'+\n      '<span class=\"chip '+(dep?'on':'bad')+'\">依赖 '+(dep?'齐':'缺')+'</span>'+\n      '<span class=\"chip '+(comp?'on':'bad')+'\">编译 '+(comp?'过':'报错')+'</span>'+\n      '<span class=\"chip '+(main?'on':'bad')+'\">主类/端口 '+(main?'对':'错')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(ok?'运行':'定位')+'</span>'+\n      (ok?'四条件齐 → java -jar 启动服务进程, 监听端口等请求。':'缺「'+stage+'」→ 先修这一段, 不要乱猜业务逻辑。分段查: 环境→源码→启动→业务。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">JDK='+jdk+' 依赖='+dep+' 编译='+comp+' 主类='+main+'</span></div>',\n      '<div><span class=\"'+(ok?'ok':'err')+'\">状态 = '+stage+'</span></div>',\n      '<div><span class=\"c\">// 跑不起来先定位在哪一段, 再修那一段</span></div>'\n    ].join('');\n  }\n  ['g1jdk','g1dep','g1comp','g1main'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 后端在售货机比喻里负责？\",\"opts\":[[\"中间判断: 认格/查货/扣钱/出货\",true,\"对。前端按钮/库记住。\"],[\"屏幕和按钮\",false,\"那是前端。\"],[\"库存表\",false,\"那是数据库。\"]]},{\"q\":\"2. 把扣钱逻辑写进前端按钮会？\",\"opts\":[[\"用户改页面就绕过扣钱\",true,\"对。核心判断必须在后端。\"],[\"更安全\",false,\"恰恰更危险。\"],[\"运行更快\",false,\"无关。\"]]},{\"q\":\"3. .java 到服务进程顺序？\",\"opts\":[[\"源码→字节码→JVM→JAR→进程\",true,\"对。编译后由 JVM 执行。\"],[\"源码直接机器执行\",false,\"需编译+JVM。\"],[\"JAR→源码→JVM\",false,\"顺序反了。\"]]},{\"q\":\"4. IDEA 本身负责编译运行吗？\",\"opts\":[[\"不, 它调用 JDK\",true,\"对。IDEA 管写和调。\"],[\"是, 自带编译器\",false,\"靠 JDK。\"],[\"只负责打包\",false,\"打包靠 Maven。\"]]},{\"q\":\"5. Maven 管什么？\",\"opts\":[[\"依赖下载+编译+打包+测试\",true,\"对。按 pom.xml。\"],[\"只写代码\",false,\"那是 IDE。\"],[\"只存数据\",false,\"那是数据库。\"]]},{\"q\":\"6. 断点的作用是？\",\"opts\":[[\"把猜变成看: 停行/看变量/单步\",true,\"对。调试核心。\"],[\"加快编译\",false,\"无关。\"],[\"自动修 bug\",false,\"只帮你观察。\"]]}];" },
    "backend|java|Java 本身：对象、集合与并发": { "body": "<p class=\"lead\">不靠任何框架，把 Java 本身摸熟：变量类型、类与对象、集合、异常、Stream、并发基础，最后独立写出一个像样的用户管理模块。类是模具，对象是压出来的饼干。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">模具</span><span class=\"s\">类与对象</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">收纳</span><span class=\"s\">集合怎么选</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">兜底</span><span class=\"s\">异常/Stream/并发</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>给全班做名牌：先做模板，再填谁的信息</h2>\n    <p>先讲个故事。给全班做名牌，你不会一张张从零画，而是先做一个模板：名字、学号、班级三个空位，填谁的信息就是谁的名牌。这个模板就是<span class=\"term\">类</span>，做出来的每张名牌就是<span class=\"term2\">对象</span>。一个模具能压很多块饼干。</p>\n    <p>变量是贴了标签的盒子，<b>类型</b>规定盒子能装什么：装整数的盒子塞不进一句话，编译器先替你检查。Java 是强类型：声明必须给类型。基本类型 int/long/double/boolean/char；引用类型 String/对象/数组。boolean 是真 true/false 不是 0/1；char 是 16 位 Unicode 能存中文。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>类是图纸/模具，对象是造出来的东西/饼干；变量=贴标签盒子，类型=能装什么。</div>\n    <div class=\"recap\"><b>收束：</b>类→对象(实例化)；强类型编译期检查；基本 vs 引用类型。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>面向对象：封装、继承、多态、接口</h2>\n    <p><b>封装</b>=把数据和方法装一起、对外只露该露的(私有字段+公开方法)，像名牌模板只留三个空位不让你乱改内部。<b>继承</b>=子类复用父类并扩展(学生名牌→班干部名牌加职务)。<b>多态</b>=同一调用不同对象表现不同(「打印名牌」对普通/班干部各自格式)。<b>接口</b>=约定「能做什么」不管「怎么做」(可打印接口)。</p>\n    <p>面向对象的收益：改一处不影响其它(封装)、复用不重写(继承)、加新类型不改旧代码(多态+接口)。写用户管理模块时：User 类封装字段+校验方法，UserService 面向接口编程，换实现不改调用方。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"类是模具对象是饼干\">\n        <rect x=\"8\" y=\"26\" width=\"220\" height=\"70\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"118\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">类 User(模具)</text><text x=\"118\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">name/id/class 空位+方法</text><text x=\"118\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">封装: 私有字段+公开方法</text>\n        <rect x=\"300\" y=\"14\" width=\"140\" height=\"40\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"370\" y=\"38\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#1E7268\">对象 alice</text>\n        <rect x=\"300\" y=\"62\" width=\"140\" height=\"40\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"370\" y=\"86\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#1E7268\">对象 bob</text>\n        <rect x=\"300\" y=\"110\" width=\"140\" height=\"40\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"370\" y=\"134\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#1E7268\">对象 carol</text>\n        <line x1=\"228\" y1=\"60\" x2=\"298\" y2=\"34\" stroke=\"#A39B8E\" stroke-width=\"2\"/>\n        <line x1=\"228\" y1=\"60\" x2=\"298\" y2=\"82\" stroke=\"#A39B8E\" stroke-width=\"2\"/>\n        <line x1=\"228\" y1=\"60\" x2=\"298\" y2=\"130\" stroke=\"#A39B8E\" stroke-width=\"2\"/>\n        <rect x=\"480\" y=\"26\" width=\"272\" height=\"70\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"616\" y=\"52\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">继承/多态/接口</text><text x=\"616\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">复用/同调用不同表现/约定能力</text><text x=\"616\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">加新类型不改旧代码</text>\n        <text x=\"380\" y=\"166\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">一个模具压很多饼干；改模具不影响已压好的饼干各自数据</text>\n      </svg>\n      <figcaption>图 1 · 类=模具、对象=饼干；封装/继承/多态/接口各司其职。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>封装藏内部、继承受复用、多态同调用不同表现、接口约定能力。</div>\n    <div class=\"recap\"><b>收束：</b>四特性+面向接口编程+改一处不影响其它。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>集合怎么选：要不要排队、能不能重复、要不要贴标签</h2>\n    <p>一堆数据怎么收？按三问选：<b>要不要排队/有序</b>→<span class=\"term\">List</span>(ArrayList 有序可重复,按索引取)；<b>能不能重复</b>→不要重复用 <span class=\"term\">Set</span>(HashSet 去重)；<b>要不要贴标签/键值</b>→<span class=\"term2\">Map</span>(HashMap 键→值,按 key 快速取)。用户管理里：用户列表用 List、去重学号用 Set、按 id 查用户用 Map。</p>\n    <p>遍历用 for-each 或迭代器；边遍历边删要用迭代器 remove 否则 ConcurrentModificationException。Map 取值先 containsKey 或 getOrDefault 防 null。选错集合=要么慢(List 查 id 要遍历)要么错(List 不去重)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>集合三问：排队→List、去重→Set、贴标签→Map；按 id 查用 Map 别用 List 遍历。</div>\n    <div class=\"recap\"><b>收束：</b>List/Set/Map 三问选型+遍历删除用迭代器+getOrDefault 防 null。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>异常与 Stream：出错兜底、批量处理</h2>\n    <p><b>异常</b>=出错了怎么办。try 包可能错的代码、catch 分类处理、finally 必做收尾。受检异常必须处理或声明抛出；运行时异常(空指针/越界)靠预防。别 catch 了吞掉(空 catch)——至少记日志或转成业务错误。自定义 BusinessException 带错误码，让上层统一返回。</p>\n    <p><span class=\"term\">Stream</span>=批量处理流水线：filter(筛)→map(变换)→sorted(排)→collect(收)。如「筛出活跃用户→取名字→排序→收 List」。Stream 不修改源集合、懒执行、一次性。配合 Optional 防 null：<code>Optional.ofNullable(u).map(User::getName).orElse(\"匿名\")</code>。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>异常分类处理别吞掉；Stream=filter/map/sorted/collect 流水线，不改源、一次性。</div>\n    <div class=\"recap\"><b>收束：</b>try/catch/finally+受检vs运行时+自定义业务异常+Stream 四步+Optional。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>并发基础：几件事同时干，共享数据要加锁</h2>\n    <p><b>线程</b>=同时干几件事。new Thread/Runnable 或线程池 ExecutorService 提交任务。多线程读同一数据没事，<b>写同一数据</b>会竞态(两人同时扣库存超卖)。解法：<span class=\"term\">synchronized</span>/Lock 加锁、原子类 AtomicInteger、并发集合 ConcurrentHashMap。</p>\n    <p>新手坑：以为「我本机单线程跑没问题」=并发安全；HashMap 多线程写可能死循环/丢数据→换 ConcurrentHashMap；锁粒度太大=串行慢、太小=没护住。用户管理模块里「扣积分/改余额」必须加锁或原子操作。过关：独立写用户类+集合操作+异常处理+基本并发安全。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>多线程写共享数据要加锁/原子/并发集合；本机单线程跑过≠并发安全。</div>\n    <div class=\"recap\"><b>收束：</b>线程/线程池+竞态+锁/原子/并发集合+锁粒度+扣余额必须护。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：手绘 vs 模具、集合选型沙盒</h2>\n    <p>演练一看「一张张手绘名牌」和「模板压饼干」的差别。演练二勾选三个需求（排队/去重/贴标签），看该选 List/Set/Map 及按 id 查的代价。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种做法</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"hand\" class=\"on\">❌ 一张张手绘</button><button data-k=\"mold\">✅ 模板压饼干</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个班级名牌，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 集合选型沙盒</b><span class=\"hint\">勾选三个需求</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1order\" checked> 要排队/有序</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1dup\"> 要去重</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1key\"> 要贴标签/按key查</label></div>\n        <div class=\"ctl\"><label>元素数</label><input type=\"range\" id=\"g1n\" min=\"10\" max=\"100000\" value=\"10000\"><span class=\"val\" id=\"g1nV\">10000</span></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">按 key 查: Map≈O(1) vs List≈O(n)；元素越多差距越大</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>手绘=改一个字段要重画全部；模具=改模板一次生效。按 id 查用户用 Map；用 List 遍历在十万级会明显慢。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经能把 Java 本身当工具用。下一课学 Web 的通用语言。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>类/对象</td><td>模具/饼干</td><td>图纸 vs 实例</td></tr>\n      <tr><td>强类型</td><td>盒子能装什么</td><td>编译期检查</td></tr>\n      <tr><td>封装/继承/多态/接口</td><td>藏/复用/同调用不同/约定</td><td>面向接口编程</td></tr>\n      <tr><td>List/Set/Map</td><td>排队/去重/贴标签</td><td>三问选型</td></tr>\n      <tr><td>异常</td><td>出错兜底</td><td>try/catch/finally, 别吞</td></tr>\n      <tr><td>Stream</td><td>批量流水线</td><td>filter/map/sorted/collect</td></tr>\n      <tr><td>并发</td><td>同时干+共享加锁</td><td>锁/原子/并发集合</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，复杂度为量级示意；沙盒为模拟推导。口径以初级 README 与第二篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第二篇-快速掌握Java <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 过关标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://dev.java/learn/\" target=\"_blank\" rel=\"noopener\">Dev.java Learn</a> <span class=\"src\">— 语言核心</span></li>\n        <li><a href=\"https://docs.oracle.com/javase/tutorial/collections/\" target=\"_blank\" rel=\"noopener\">Oracle Collections Trail</a> <span class=\"src\">— List/Set/Map</span></li>\n        <li><a href=\"https://docs.oracle.com/javase/tutorial/essential/concurrency/\" target=\"_blank\" rel=\"noopener\">Oracle Concurrency Trail</a> <span class=\"src\">— 线程/锁</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://developer.mozilla.org/zh-CN/docs/Web/HTTP\" target=\"_blank\" rel=\"noopener\">MDN HTTP</a> <span class=\"src\">— B3 Web 通用语言</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"模具与饼干"},{"id":"b","title":"面向对象四特性"},{"id":"c","title":"集合三问"},{"id":"d","title":"异常/Stream"},{"id":"e","title":"并发基础"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var HAND=\"// ❌ 一张张手绘名牌\\n改一个字段 → 重画全部 40 张\\n数据和方法散在各处\\n加新类型 → 改所有旧代码\\n没有复用, 越写越乱\";\n  var MOLD=\"// ✅ 模板(类)压饼干(对象)\\n class User { name; id; clazz; 方法 }\\n new User(...) → alice/bob/carol\\n 封装: 私有字段+公开方法\\n 继承复用 / 多态同调用不同 / 接口约定\\n 改模板一次生效, 加新类型不改旧代码\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"hand\"?HAND:MOLD);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"hand\"?\"err\":\"ok\")+\"\\\">\"+(k===\"hand\"?\"改一处重画全部\":\"一个模具压很多饼干\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"hand\"?\"数据方法散落\":\"类是图纸对象是东西\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"hand\");\n})();\n\n// 演练二：集合选型沙盒\n(function(){\n  function chk(id){return document.getElementById(id).checked;}\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var order=chk('g1order'), dup=chk('g1dup'), key=chk('g1key'), n=val('g1n');\n    document.getElementById('g1nV').textContent=n;\n    var pick = key? 'Map' : (dup? 'Set' : 'List');\n    var lookup = key? 1 : n;   // O(1) vs O(n) 示意\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box good\"><b>'+pick+'</b><small>推荐集合</small></div>'+\n      '<div class=\"stat-box '+(key?'good':'bad')+'\"><b>'+lookup+'</b><small>按id查代价(量级)</small></div>'+\n      '<div class=\"stat-box\"><b>'+n+'</b><small>元素数</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(order?'on':'')+'\">排队 '+ (order?'要':'不要')+'</span>'+\n      '<span class=\"chip '+(dup?'on':'')+'\">去重 '+(dup?'要':'不要')+'</span>'+\n      '<span class=\"chip '+(key?'on':'bad')+'\">贴标签 '+(key?'要→Map':'不要')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">选型</span>'+\n      (key?'要按 key 查 → Map(HashMap), 查≈O(1)。':'不要 key → '+(dup?'去重 → Set(HashSet)。':'有序可重复 → List(ArrayList)。'))+(key?'':' 若 later 要按 id 查, 用 List 遍历在 '+n+' 级会慢(≈O(n))。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">排队='+order+' 去重='+dup+' 贴标签='+key+' n='+n+'</span></div>',\n      '<div><span class=\"ok\">推荐 = '+pick+'</span></div>',\n      '<div><span class=\"'+(key?'ok':'err')+'\">按id查代价 ≈ '+(key?'O(1)':'O(n)='+n)+'</span></div>',\n      '<div><span class=\"c\">// 三问选型: 排队List / 去重Set / 贴标签Map</span></div>'\n    ].join('');\n  }\n  ['g1order','g1dup','g1key'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  document.getElementById('g1n').addEventListener('input',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 类和对象的关系？\",\"opts\":[[\"类是模具/图纸, 对象是压出的饼干\",true,\"对。一个类多个对象。\"],[\"对象是模具类是饼干\",false,\"反了。\"],[\"两者无关\",false,\"实例化关系。\"]]},{\"q\":\"2. 按 id 快速查用户应选？\",\"opts\":[[\"Map(键→值)\",true,\"对。≈O(1)。\"],[\"List 遍历\",false,\"O(n) 慢。\"],[\"Set\",false,\"Set 去重不按 key 取值。\"]]},{\"q\":\"3. 要去重应选？\",\"opts\":[[\"Set\",true,\"对。HashSet 去重。\"],[\"List\",false,\"List 可重复。\"],[\"Map 键随意\",false,\"Map 是键值非单纯去重集。\"]]},{\"q\":\"4. catch 里空着吞掉异常会？\",\"opts\":[[\"出错无声无息难排查\",true,\"对。至少记日志或转业务错误。\"],[\"更安全\",false,\"掩盖问题。\"],[\"自动重试\",false,\"不会。\"]]},{\"q\":\"5. Stream 的特点？\",\"opts\":[[\"不改源/懒执行/一次性流水线\",true,\"对。filter/map/collect。\"],[\"修改源集合\",false,\"不改源。\"],[\"可重复消费\",false,\"一次性。\"]]},{\"q\":\"6. 多线程写共享余额必须？\",\"opts\":[[\"加锁/原子类/并发集合护住\",true,\"对。否则竞态超卖。\"],[\"本机单线程跑过就安全\",false,\"并发不安全。\"],[\"用 HashMap 即可\",false,\"多线程写 HashMap 危险。\"]]}];" },
    "backend|java|Web 通用语言：HTTP、REST 与 JSON": { "body": "<p class=\"lead\">学会 Web 的通用语言：HTTP 请求与响应、状态码、REST 风格 URL、JSON 标准点菜单、用 curl/Postman 自测接口、前后端数据怎么递来递去。学完再看 Spring Boot 注解就不觉得从天而降。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">对话</span><span class=\"s\">请求/响应/状态码</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">规矩</span><span class=\"s\">REST/JSON</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">自测</span><span class=\"s\">curl/Postman</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>点菜：你说的话是请求，端回来的是响应</h2>\n    <p>先讲个故事。餐厅点菜你说「要一份宫保鸡丁」，服务员要么端上来、要么说「卖完了」、要么说「厨房着火了稍等」。这就是一次 HTTP：你说的话=<b>请求</b>，端回来的=<b>响应</b>，「卖完了/着火了」=<b>状态码</b>。</p>\n    <p>HTTP 是客户端和服务器通信的规则，浏览器开网页、App 调接口都用它。一次交互=客户端发请求→服务器处理→返回响应。<b>无状态</b>：每次请求独立，服务器不记得上一次（靠 Token/Cookie 带身份）。理解这点才懂为什么每个接口都要带 Authorization。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>HTTP=一次有来有回的对话；请求=点单、响应=端菜、状态码=结果类别；无状态靠 Token 带身份。</div>\n    <div class=\"recap\"><b>收束：</b>请求/响应/状态码三件+无状态+每请求带身份。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>请求三 parts 与状态码家族</h2>\n    <p>请求像点单条：<b>方法</b>说「要做什么」(GET 看一眼/POST 下一单/PUT 改/DELETE 删)、<b>路径</b>说「找谁」(/api/users/1)、<b>Header</b> 是附加说明(Content-Type/Authorization)、<b>Body</b> 才是具体内容(JSON)。响应 likewise：状态码+Header+Body。</p>\n    <p>状态码家族：<span class=\"term\">2xx</span> 成功(200 OK/201 创建)、<span class=\"term\">3xx</span> 重定向、<span class=\"term2\">4xx</span> 客户端错(400 参数错/401 没登录/403 没权限/404 不存在)、<span class=\"term2\">5xx</span> 服务器错(500 内部错/503 不可用)。<b>别全返回 200</b>：把「卖完了」也说成「端上来」，前端没法区分成功失败。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"HTTP 一次对话与状态码家族\">\n        <defs><marker id=\"arb3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"220\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"118\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">客户端(点单)</text><text x=\"118\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">方法+路径+Header+Body</text>\n        <rect x=\"532\" y=\"26\" width=\"220\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"642\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">服务器(端菜)</text><text x=\"642\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">状态码+Header+Body</text>\n        <line x1=\"228\" y1=\"44\" x2=\"530\" y2=\"44\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb3)\"/>\n        <line x1=\"530\" y1=\"66\" x2=\"230\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb3)\"/>\n        <rect x=\"8\" y=\"104\" width=\"170\" height=\"44\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"93\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#1E7268\">2xx 成功/创建</text>\n        <rect x=\"196\" y=\"104\" width=\"170\" height=\"44\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"281\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#8A5510\">3xx 重定向</text>\n        <rect x=\"384\" y=\"104\" width=\"170\" height=\"44\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"469\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#B04A35\">4xx 客户端错</text>\n        <rect x=\"572\" y=\"104\" width=\"180\" height=\"44\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"662\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#B04A35\">5xx 服务器错</text>\n      </svg>\n      <figcaption>图 1 · 一次有来有回；状态码告诉前端结果属于哪一类。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>请求=方法+路径+Header+Body；状态码分家族；401 没登录/403 没权限/404 不存在别混。</div>\n    <div class=\"recap\"><b>收束：</b>请求四件+响应三件+2/3/4/5xx 家族+别全 200。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>REST 定 URL 规矩，JSON 定内容格式</h2>\n    <p><span class=\"term\">REST</span>=用 URL 表示资源、用方法表示动作：GET /users 查列表、GET /users/1 查一个、POST /users 新建、PUT /users/1 改、DELETE /users/1 删。URL 用名词复数、层级表示归属(/users/1/orders)，别把动作塞 URL(/getUserById 是反模式)。</p>\n    <p><span class=\"term2\">JSON</span>=标准点菜单：键值对、字符串双引号、数组[]、对象{}、数字/布尔/null。前后端约定 Content-Type: application/json。字段命名统一(驼峰或下划线选一种)，日期用 ISO 字符串，金额用整数分或字符串防浮点误差。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>REST=资源名词+方法动作；JSON=双引号键值标准格式；字段命名/日期/金额约定统一。</div>\n    <div class=\"recap\"><b>收束：</b>REST 五动作+名词复数层级+JSON 语法+命名/日期/金额约定。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>用 curl/Postman 自测接口，别靠前端猜</h2>\n    <p>后端写完接口要<b>自己先测</b>：curl 一行发请求看响应，或 Postman/IDEA HTTP Client 图形化测。例：<code>curl -X POST localhost:8080/api/users -H \"Content-Type: application/json\" -d '{\"name\":\"alice\"}'</code>→看状态码 201+Body。把常用请求存成 test.http / Postman 集合，回归时一键重跑。</p>\n    <p>测什么：正常路径(201/200)、参数错(400)、没登录(401)、没权限(403)、不存在(404)。<b>故意触发错误</b>确认错误返回明确，而不是 500 一锅端。自测过再交给前端，减少「你接口是不是坏了」的扯皮。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>接口自己先测：curl/Postman 存集合；正常+400/401/403/404 都故意触发一遍。</div>\n    <div class=\"recap\"><b>收束：</b>curl/Postman/test.http+正常与错误路径都测+存集合回归。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>前后端交互完整流程：从点击到渲染</h2>\n    <p>一次完整交互：用户点击→前端组装请求(方法/路径/Header 带 Token/Body JSON)→发 HTTP→后端拦截器验 Token→Controller 收参校验→Service 判断→Repository 查库→组装响应 JSON+状态码→前端收响应→按状态码分支(成功渲染/401 跳登录/400 提示)→更新界面。</p>\n    <p>跨域(CORS)是浏览器安全机制：前端域名≠后端域名时浏览器拦响应，需后端配 Access-Control-Allow-*。开发期常用代理绕过。理解整条链，出错时知道是前端没带 Token、后端没验、还是库没数据。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>点击→组装→HTTP→验Token→三层→响应→前端分支渲染；跨域靠 CORS/代理；出错分段定位。</div>\n    <div class=\"recap\"><b>收束：</b>完整交互链+CORS+分段定位+前端按状态码分支。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：状态码乱返回 vs 正确、点单方法沙盒</h2>\n    <p>演练一看「全返回 200」和「正确状态码」的差别。演练二选一个点单场景（查/增/改/删），看该用的方法+URL+成功状态码。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种状态码</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"all200\" class=\"on\">❌ 全返回 200</button><button data-k=\"proper\">✅ 正确状态码</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一句「卖完了」，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 点单方法沙盒</b><span class=\"hint\">点场景按钮</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e2\"><button data-k=\"list\" class=\"on\">查列表</button><button data-k=\"create\">新建</button><button data-k=\"update\">修改</button><button data-k=\"delete\">删除</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">REST: 资源名词+方法动作；成功状态码 200/201/204</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>全 200 让前端无法区分成功/没登录/不存在；正确状态码让前端按类分支。查=GET、增=POST 201、改=PUT、删=DELETE 204。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会说 Web 的通用语言。下一课看懂 Spring Boot 三层。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>HTTP</td><td>点菜一次对话</td><td>请求/响应/无状态</td></tr>\n      <tr><td>请求四件</td><td>点单条</td><td>方法/路径/Header/Body</td></tr>\n      <tr><td>状态码家族</td><td>结果类别</td><td>2/3/4/5xx; 401/403/404</td></tr>\n      <tr><td>REST</td><td>资源名词+方法动作</td><td>GET/POST/PUT/DELETE</td></tr>\n      <tr><td>JSON</td><td>标准点菜单</td><td>双引号键值/命名/金额约定</td></tr>\n      <tr><td>自测</td><td>curl/Postman</td><td>正常+错误路径都测</td></tr>\n      <tr><td>交互链/CORS</td><td>点击到渲染</td><td>分段定位+跨域配 CORS</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，URL/命令为示例；沙盒为模拟推导。口径以初级 README 与第三篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第三篇-理解Web开发 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 过关标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://developer.mozilla.org/zh-CN/docs/Web/HTTP\" target=\"_blank\" rel=\"noopener\">MDN HTTP</a> <span class=\"src\">— 请求/响应/状态码</span></li>\n        <li><a href=\"https://restfulapi.net/\" target=\"_blank\" rel=\"noopener\">REST API Tutorial</a> <span class=\"src\">— REST 设计</span></li>\n        <li><a href=\"https://www.json.org/json-zh.html\" target=\"_blank\" rel=\"noopener\">JSON 中文</a> <span class=\"src\">— JSON 语法</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://spring.io/guides/gs/rest-service/\" target=\"_blank\" rel=\"noopener\">Spring REST Guide</a> <span class=\"src\">— B4 Spring Boot 三层</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"点菜对话"},{"id":"b","title":"请求/状态码"},{"id":"c","title":"REST/JSON"},{"id":"d","title":"自测接口"},{"id":"e","title":"交互链/CORS"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var ALL=\"// ❌ 全返回 200\\n卖完了 → 200 {msg:\\\"卖完了\\\"}\\n没登录 → 200 {msg:\\\"请先登录\\\"}\\n不存在 → 200 {msg:\\\"没有\\\"}\\n前端无法按状态码分支\\n成功/失败混在一起, 靠猜 msg\";\n  var PROPER=\"// ✅ 正确状态码\\n成功 → 200 / 创建 201\\n参数错 → 400\\n没登录 → 401\\n没权限 → 403\\n不存在 → 404\\n服务器错 → 500\\n前端按类分支: 渲染/跳登录/提示\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"all200\"?ALL:PROPER);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"all200\"?\"err\":\"ok\")+\"\\\">\"+(k===\"all200\"?\"前端无法区分成功失败\":\"前端按状态码类别分支\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"all200\"?\"把卖完了也说成端上来\":\"状态码=结果类别\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"all200\");\n})();\n\n// 演练二：点单方法沙盒\n(function(){\n  var MAP={\n    list:{m:'GET',url:'/api/users',code:200,desc:'查列表: 看一眼, 不改数据'},\n    create:{m:'POST',url:'/api/users',code:201,desc:'新建: 下一单, 返回创建结果'},\n    update:{m:'PUT',url:'/api/users/1',code:200,desc:'修改: 改已有资源'},\n    delete:{m:'DELETE',url:'/api/users/1',code:204,desc:'删除: 移除资源, 无 Body'}\n  };\n  function show(k){\n    var d=MAP[k];\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box good\"><b>'+d.m+'</b><small>方法</small></div>'+\n      '<div class=\"stat-box\"><b>'+d.code+'</b><small>成功状态码</small></div>'+\n      '<div class=\"stat-box\"><b>'+d.url+'</b><small>路径</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip on\">'+d.m+' '+d.url+'</span>'+\n      '<span class=\"chip on\">成功 '+d.code+'</span>'+\n      '<span class=\"chip\">资源名词 users</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">REST</span>'+d.desc+'。URL 用名词复数, 动作交给方法; 别写 /getUserById。';\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">场景='+k+' → '+d.m+' '+d.url+'</span></div>',\n      '<div><span class=\"ok\">成功状态码='+d.code+'</span></div>',\n      '<div><span class=\"c\">// REST: 资源名词+方法动作</span></div>'\n    ].join('');\n  }\n  document.querySelectorAll(\"#e2 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e2 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"list\");\n})();\n\nconst QUIZ=[{\"q\":\"1. HTTP 无状态意味着？\",\"opts\":[[\"每次请求独立, 靠 Token 带身份\",true,\"对。服务器不记得上次。\"],[\"服务器记住所有历史\",false,\"那是有状态。\"],[\"不需要身份\",false,\"仍需 Token。\"]]},{\"q\":\"2. 没登录应返回？\",\"opts\":[[\"401\",true,\"对。403 是没权限。\"],[\"200\",false,\"别全 200。\"],[\"404\",false,\"404 是不存在。\"]]},{\"q\":\"3. REST 新建资源用？\",\"opts\":[[\"POST /users, 201\",true,\"对。资源名词+方法动作。\"],[\"GET /createUser\",false,\"动作塞 URL 反模式。\"],[\"DELETE /users\",false,\"那是删除。\"]]},{\"q\":\"4. JSON 字符串必须？\",\"opts\":[[\"双引号\",true,\"对。单引号非法。\"],[\"单引号\",false,\"非法。\"],[\"可不加引号\",false,\"键必须引号。\"]]},{\"q\":\"5. 接口写完应先？\",\"opts\":[[\"自己 curl/Postman 测正常+错误路径\",true,\"对。再交前端。\"],[\"直接交前端猜\",false,\"扯皮源头。\"],[\"只测正常路径\",false,\"错误也要触发。\"]]},{\"q\":\"6. 跨域被浏览器拦应？\",\"opts\":[[\"后端配 CORS 或开发期代理\",true,\"对。浏览器安全机制。\"],[\"关浏览器安全\",false,\"不可取。\"],[\"改前端域名必相同\",false,\"可用 CORS/代理。\"]]}];" },
    "backend|java|看懂 Spring Boot：三层与依赖注入": { "body": "<p class=\"lead\">不从零建项目，而是给你一份完整源码带你看懂：一条 HTTP 请求怎么穿过 Controller→Service→Repository→数据库，每个注解替你省了什么，统一响应和全局异常怎么悄悄生效。看懂了再改小功能就不慌。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">分层</span><span class=\"s\">窗口/科室/档案室</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">追请求</span><span class=\"s\">一条请求流转</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">认注解</span><span class=\"s\">DI/事务/异常</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>办事大厅：窗口收材料、科室判断、档案室存取</h2>\n    <p>先讲个故事。去办事大厅你不会自己冲进档案室翻柜子。<b>窗口</b>收材料给回执；<b>业务科室</b>判断能不能办；<b>档案室</b>只负责存取。Spring Boot 项目就这么分层：<span class=\"term\">Controller</span>=窗口、<span class=\"term\">Service</span>=科室、<span class=\"term2\">Repository</span>=档案室。</p>\n    <p>学编程像学修车：不需要从零造车，只要能拆开引擎看懂每个零件作用。本课给你完整源码，目标不是「从零敲出」而是「看懂」：每层在做什么、请求怎么流转、每个注解解决什么问题。看懂了改一个小功能就不慌。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Controller 窗口/Service 科室/Repository 档案室；每层只干自己的活，剩下交给 Spring 容器。</div>\n    <div class=\"recap\"><b>收束：</b>三层比喻+看懂而非照抄+每层职责单一。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>追一条请求：从 HTTP 到数据库再回来</h2>\n    <p>以「用户发消息」为例：HTTP POST /api/chat/messages→<b>Controller</b> 用 @PostMapping 收参、@RequestBody 把 JSON 转 DTO、校验→调 <b>Service</b> 方法→Service 做业务判断(扣积分/组装上下文)→调 <b>Repository</b>(MyBatis-Plus Mapper)→SQL 落库→返回实体→Service 转 VO→Controller 包统一响应→JSON 回前端。</p>\n    <p>每层只干自己的活：Controller 不写业务 SQL、Service 不碰 HTTP 细节、Repository 不做业务判断。出错时按层定位：参数错看 Controller、逻辑错看 Service、数据错看 Repository/SQL。<b>画出这条流转图</b>是本课过关标准之一。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"请求穿过三层\">\n        <defs><marker id=\"arb4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"93\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">Controller 窗口</text><text x=\"93\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">收参/校验/包响应</text>\n        <rect x=\"200\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"285\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">Service 科室</text><text x=\"285\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">业务判断/编排/事务</text>\n        <rect x=\"392\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"477\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">Repository 档案室</text><text x=\"477\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">Mapper/SQL 存取</text>\n        <rect x=\"584\" y=\"26\" width=\"168\" height=\"56\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"668\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5B4A2F\">数据库</text><text x=\"668\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">记住/取回</text>\n        <line x1=\"178\" y1=\"44\" x2=\"198\" y2=\"44\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb4)\"/>\n        <line x1=\"370\" y1=\"44\" x2=\"390\" y2=\"44\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb4)\"/>\n        <line x1=\"562\" y1=\"44\" x2=\"582\" y2=\"44\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb4)\"/>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">参数错看 Controller / 逻辑错看 Service / 数据错看 Repository+SQL</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">Controller 不写 SQL, Service 不碰 HTTP, Repository 不做业务判断</text>\n      </svg>\n      <figcaption>图 1 · 一条请求穿过三层到数据库再回来；每层只干自己的活。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>请求顺三层走；DTO 进/VO 出；出错按层定位；能画流转图才算看懂。</div>\n    <div class=\"recap\"><b>收束：</b>流转链+DTO/VO+按层定位+画图为过关。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>依赖注入：Spring 容器替你 new 和装配</h2>\n    <p><span class=\"term\">依赖注入(DI)</span>/<span class=\"term2\">控制反转(IoC)</span>=你不自己 new 依赖，而是声明「我需要 UserService」，Spring 容器创建并塞给你(@Autowired/构造注入)。好处：换实现不改调用方、便于测试(塞 mock)、生命周期容器管。</p>\n    <p>认注解：@RestController=@Controller+@ResponseBody(返回 JSON)；@Service/@Repository 标记组件被扫描；@Autowired/构造器注入依赖；@RequestMapping/@GetMapping/@PostMapping 映射 URL；@RequestBody/@PathVariable/@RequestParam 收参。<b>构造注入优于字段注入</b>：依赖明确、可 final、易测试。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>DI=声明需要而非自己 new，容器装配；构造注入优于字段注入；注解各管映射/收参/标记。</div>\n    <div class=\"recap\"><b>收束：</b>DI/IoC+容器装配+构造注入+关键注解清单。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>事务、校验、全局异常：悄悄生效的三件事</h2>\n    <p><b>事务</b> @Transactional：一组操作要么全成要么全回滚(扣积分+写日志必须同成败)。注意自调用失效(同类内方法互调不走代理)、默认只回滚 RuntimeException。<b>校验</b> @Valid+@NotBlank/@Size：参数不合法自动 400，别手写一堆 if。<b>全局异常</b> @RestControllerAdvice+@ExceptionHandler：把散落各处的 try/catch 收敛成统一错误响应(错误码+消息)，Controller 保持干净。</p>\n    <p>统一响应包 Result{code,msg,data}：成功 code=0/200、失败带业务错误码；前端只看 code 分支。这三件事+统一响应让「重复代码」消失，业务代码只写业务。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>@Transactional 同成败(防自调用)、@Valid 自动 400、@RestControllerAdvice 统一错误；Result 统一响应。</div>\n    <div class=\"recap\"><b>收束：</b>事务/校验/全局异常/统一响应四件+自调用坑+只回滚 RuntimeException。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>动手改一个功能：在已有项目里加一小块</h2>\n    <p>看懂后改小功能练手：如给「会话」加一个「置顶」字段。步骤：Entity 加字段+数据库列→Mapper/Repository 无需改(MyBatis-Plus 自动)→Service 加 toggleTop 方法(业务判断)→Controller 加 @PutMapping /sessions/{id}/top→DTO/VO 加字段→test.http 加请求自测→跑通。</p>\n    <p>改的过程验证你真看懂：知道字段加哪层、逻辑放 Service、URL 放 Controller、响应包 Result。过关：项目能启动 test.http 全跑通、能画「用户发消息」流转图、能说出每个 Controller/Service/Repository/Entity/DTO 文件作用。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>改小功能=按层加字段/逻辑/URL/响应+自测；能说出每个文件作用才算看懂。</div>\n    <div class=\"recap\"><b>收束：</b>加字段六步+按层放置+test.http 自测+文件作用过关。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：一锅炖 vs 三层、请求流转沙盒</h2>\n    <p>演练一看「Controller 里写 SQL 一锅炖」和「三层各司其职」的差别。演练二勾选四个机制（分层/DI/全局异常/事务），看请求能否正确落库、出错能否回滚与统一返回。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种组织</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"pot\" class=\"on\">❌ 一锅炖</button><button data-k=\"layer\">✅ 三层各司其职</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个发消息接口，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 请求流转沙盒</b><span class=\"hint\">勾选四个机制</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1layer\" checked> 三层分离</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1di\" checked> 依赖注入</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1adv\" checked> 全局异常</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1tx\" checked> 事务 @Transactional</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">模拟「扣积分成功但写日志失败」：有事务回滚 / 无事务脏数据</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>一锅炖改一处牵全身、出错无处查；三层+DI+全局异常+事务让请求正确落库、失败回滚、错误统一返回。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经能看懂一个 Spring Boot 项目。下一课补账号系统这把门锁。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>三层</td><td>窗口/科室/档案室</td><td>Controller/Service/Repository</td></tr>\n      <tr><td>请求流转</td><td>HTTP→三层→库→回</td><td>DTO 进/VO 出/按层定位</td></tr>\n      <tr><td>DI/IoC</td><td>声明需要容器装配</td><td>构造注入优于字段</td></tr>\n      <tr><td>@Transactional</td><td>同成败</td><td>防自调用/只回滚 Runtime</td></tr>\n      <tr><td>@Valid</td><td>自动 400</td><td>别手写 if 校验</td></tr>\n      <tr><td>@RestControllerAdvice</td><td>统一错误</td><td>收敛 try/catch</td></tr>\n      <tr><td>Result</td><td>统一响应</td><td>code/msg/data</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，注解/步骤为示例；沙盒为模拟推导。口径以初级 README 与第四篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第四篇-掌握SpringBoot <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 过关标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://spring.io/guides/gs/rest-service/\" target=\"_blank\" rel=\"noopener\">Spring REST Guide</a> <span class=\"src\">— 三层与注解</span></li>\n        <li><a href=\"https://docs.spring.io/spring-framework/reference/core/beans.html\" target=\"_blank\" rel=\"noopener\">Spring IoC Container</a> <span class=\"src\">— 依赖注入</span></li>\n        <li><a href=\"https://baomidou.com/\" target=\"_blank\" rel=\"noopener\">MyBatis-Plus</a> <span class=\"src\">— Repository/Mapper</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://jwt.io/introduction\" target=\"_blank\" rel=\"noopener\">JWT Introduction</a> <span class=\"src\">— B5 账号系统令牌</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"办事大厅分层"},{"id":"b","title":"追一条请求"},{"id":"c","title":"依赖注入"},{"id":"d","title":"事务/校验/异常"},{"id":"e","title":"改一个功能"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var POT=\"// ❌ Controller 一锅炖\\n@PostMapping 里直接写 SQL+业务+try/catch\\n改一处牵全身\\n出错不知道看哪层\\n没法单测 Service\\n重复代码到处都是\";\n  var LAYER=\"// ✅ 三层各司其职\\nController: 收参/校验/包 Result\\nService: 业务判断/编排/@Transactional\\nRepository: Mapper/SQL 存取\\nDI 容器装配, 全局异常统一错误\\n参数错看C / 逻辑错看S / 数据错看R\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"pot\"?POT:LAYER);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"pot\"?\"err\":\"ok\")+\"\\\">\"+(k===\"pot\"?\"改一处牵全身+无处查\":\"各管一段+按层定位\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"pot\"?\"窗口冲进档案室翻柜子\":\"窗口/科室/档案室各司其职\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"pot\");\n})();\n\n// 演练二：请求流转沙盒\n(function(){\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var layer=chk('g1layer'), di=chk('g1di'), adv=chk('g1adv'), tx=chk('g1tx');\n    var rollback = tx;             // 扣积分成功写日志失败 → 有事务回滚\n    var unified = adv;             // 错误统一返回\n    var ok = layer&&di;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(ok?'good':'bad')+'\"><b>'+(ok?'结构清晰':'结构混乱')+'</b><small>分层+DI</small></div>'+\n      '<div class=\"stat-box '+(rollback?'good':'bad')+'\"><b>'+(rollback?'回滚':'脏数据')+'</b><small>部分失败</small></div>'+\n      '<div class=\"stat-box '+(unified?'good':'bad')+'\"><b>'+(unified?'统一':'散落')+'</b><small>错误返回</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(layer?'on':'bad')+'\">分层 '+(layer?'有':'无')+'</span>'+\n      '<span class=\"chip '+(di?'on':'bad')+'\">DI '+(di?'有':'无')+'</span>'+\n      '<span class=\"chip '+(adv?'on':'bad')+'\">全局异常 '+(adv?'有':'无')+'</span>'+\n      '<span class=\"chip '+(tx?'on':'bad')+'\">事务 '+(tx?'有':'无')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>模拟「扣积分成功但写日志失败」：'+(tx?'有 @Transactional → 整体回滚, 不丢积分不脏数据。':'无事务 → 积分扣了日志没写, 脏数据!')+(adv?' 错误经全局异常统一返回错误码。':' 错误散落各处 try/catch, 返回格式不一。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">分层='+layer+' DI='+di+' 全局异常='+adv+' 事务='+tx+'</span></div>',\n      '<div><span class=\"'+(rollback?'ok':'err')+'\">部分失败 → '+(rollback?'回滚':'脏数据')+'</span></div>',\n      '<div><span class=\"'+(unified?'ok':'err')+'\">错误返回 → '+(unified?'统一':'散落')+'</span></div>',\n      '<div><span class=\"c\">// 三层+DI+全局异常+事务 = 正确落库/失败回滚/统一错误</span></div>'\n    ].join('');\n  }\n  ['g1layer','g1di','g1adv','g1tx'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. Service 层比喻是？\",\"opts\":[[\"业务科室: 判断能不能办\",true,\"对。窗口C/档案室R。\"],[\"窗口收材料\",false,\"那是 Controller。\"],[\"档案室存取\",false,\"那是 Repository。\"]]},{\"q\":\"2. 依赖注入的意思是？\",\"opts\":[[\"声明需要, 容器创建并装配\",true,\"对。不自己 new。\"],[\"自己 new 所有依赖\",false,\"那是反模式。\"],[\"数据库注入数据\",false,\"无关。\"]]},{\"q\":\"3. @Transactional 自调用会？\",\"opts\":[[\"失效(不走代理)\",true,\"对。同类互调坑。\"],[\"仍然生效\",false,\"不走代理。\"],[\"自动加锁\",false,\"无关。\"]]},{\"q\":\"4. 参数校验推荐？\",\"opts\":[[\"@Valid+注解自动 400\",true,\"对。别手写 if。\"],[\"手写一堆 if\",false,\"重复且易漏。\"],[\"不校验\",false,\"危险。\"]]},{\"q\":\"5. 全局异常用？\",\"opts\":[[\"@RestControllerAdvice+@ExceptionHandler\",true,\"对。统一错误响应。\"],[\"每个方法 try/catch\",false,\"散落重复。\"],[\"忽略异常\",false,\"掩盖问题。\"]]},{\"q\":\"6. 逻辑错应看哪层？\",\"opts\":[[\"Service\",true,\"对。参数C/数据R。\"],[\"Controller\",false,\"那是参数/映射。\"],[\"Repository\",false,\"那是数据/SQL。\"]]}];" },
    "backend|java|账号系统：哈希、JWT 与数据权限": { "body": "<p class=\"lead\">在同一个项目上把账号系统补完整：注册要邮箱验证码、密码要哈希存储、登录发 Token、所有接口校验「这是不是你自己的数据」。物业不抄你家钥匙原件只登记齿形，你的卡只刷得开自己家那扇门。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">门禁</span><span class=\"s\">验证码/注册/登录</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">锁芯</span><span class=\"s\">密码哈希</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">钥匙</span><span class=\"s\">JWT/拦截器/权限</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>搬进新小区办门禁：验证码证明号码是你的</h2>\n    <p>先讲个故事。搬进新小区办门禁：先拿手机号收一个临时验证码证明「这号码是我的」，再登记一户人家(注册)，物业给你一张卡(登录发 Token)，之后每次进门刷卡。关键：物业<b>不把你家钥匙原件抄一份存着</b>，只登记「齿形」；你的卡也<b>只刷得开自己家那扇门</b>。</p>\n    <p>对应到代码：验证码放 <span class=\"term\">Redis</span>(带过期时间,证明号码归属+防刷)、注册写库(密码哈希)、登录验哈希发 <span class=\"term2\">JWT</span>、之后每请求带 Token 由拦截器验、再加一行 if 校验数据归属。第四篇那个「任何人都能创建账号查任何人、密码没加密」的漏洞，本课补上。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>密码只存哈希、Token 先验再放行、有 Token 也只准看自己的数据。</div>\n    <div class=\"recap\"><b>收束：</b>门禁四步比喻+Redis 验证码+哈希+JWT+数据权限补漏洞。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>验证码为什么放 Redis：过期+防刷+不占库</h2>\n    <p>验证码是<b>临时</b>凭证：5 分钟过期、用一次即废、限发送频率。放 MySQL 要自己清过期+高频写伤库；<span class=\"term\">Redis</span> 天生带 TTL(setex key 300 val)、内存快、原子 incr 限流。键设计 <code>sms:code:{email}</code>，值=码+尝试次数；验对即删、验错计数超阈作废。</p>\n    <p>为什么不用 Session 存验证码？多实例部署 Session 不共享；Redis 集中存所有实例共用。Docker 可一键拉起 Redis/MySQL 省本机安装。理解「临时+共享+快」三需求才懂选 Redis。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"账号系统完整链路\">\n        <defs><marker id=\"arb5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"88\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">发验证码</text><text x=\"88\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">Redis TTL+限流</text>\n        <rect x=\"190\" y=\"26\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"270\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">注册</text><text x=\"270\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">验码+密码哈希落库</text>\n        <rect x=\"372\" y=\"26\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"452\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">登录</text><text x=\"452\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">验哈希→发 JWT</text>\n        <rect x=\"554\" y=\"26\" width=\"198\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"653\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">带 Token 访问</text><text x=\"653\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">拦截器验签+数据权限 if</text>\n        <line x1=\"168\" y1=\"54\" x2=\"188\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb5)\"/>\n        <line x1=\"350\" y1=\"54\" x2=\"370\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb5)\"/>\n        <line x1=\"532\" y1=\"54\" x2=\"552\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arb5)\"/>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">密码只存哈希 / Token 先验再放行 / 有 Token 也只准看自己的数据</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">故意触发 401(没登录)/403(看别人)/400(码错) 确认错误明确</text>\n      </svg>\n      <figcaption>图 1 · 发码→注册→登录→带 Token 访问的完整链路。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>验证码=临时+共享+快→Redis TTL+限流+用一次即废；多实例共用不靠 Session。</div>\n    <div class=\"recap\"><b>收束：</b>Redis TTL/限流/键设计/验对即删+多实例共享+Docker 拉中间件。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>密码哈希：只登记齿形，不存钥匙原件</h2>\n    <p>明文存密码=库被拖走全部泄露。<b>哈希</b>=单向函数：密码→固定串，不可逆推；同密码同哈希(加盐后同密码不同哈希)。<span class=\"term\">BCrypt</span> 自带盐+慢哈希(抗暴力破解)，推荐；别用 MD5/SHA1(快+无盐=易彩虹表)。登录时把输入哈希后与库中哈希比对，<b>不比对明文</b>。</p>\n    <p>加盐=每用户随机盐混入再哈希，防彩虹表与「同密码同哈希」泄露关联。BCrypt 把盐嵌进结果串，无需单独存盐。传输层靠 HTTPS 防中间人窃听明文密码。哈希+盐+HTTPS 三件齐才安全。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>密码只存 BCrypt 哈希(自带盐+慢)，登录比哈希不比明文；MD5/SHA1 不行；传输靠 HTTPS。</div>\n    <div class=\"recap\"><b>收束：</b>单向哈希+加盐+BCrypt 慢哈希+登录比哈希+HTTPS。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>JWT 无状态认证：拦截器在 Controller 前挡人</h2>\n    <p><span class=\"term2\">JWT</span>=自包含令牌：header.payload.signature 三段，payload 带 userId/过期时间，signature 用服务器密钥签。<b>无状态</b>：服务器不存会话，验签+验过期即可信 payload，多实例天然共享。登录发 Token，前端存起来每请求放 Authorization: Bearer。</p>\n    <p><b>拦截器/过滤器</b>在请求到 Controller 之前验 Token：没带/过期/签错→401 挡回；验过把 userId 放请求上下文供后续用。JWT 坑：payload 只是 Base64 <b>不加密</b>别放敏感信息；密钥泄露=可伪造；过期时间要短+刷新机制；注销靠黑名单/短过期。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>JWT=签名的自包含令牌, 验签+验过期即信；拦截器 Controller 前挡人；payload 不加密别放敏感。</div>\n    <div class=\"recap\"><b>收束：</b>三段结构+无状态+拦截器前置+payload 不加密+短过期/刷新/黑名单。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>数据权限：一行 if 防用户 A 偷看用户 B</h2>\n    <p>有 Token 只证明「你是登录用户」，不证明「这数据是你的」。查/改/删任何带 id 的资源都要校验归属：<code>if (!resource.getUserId().equals(currentUserId)) throw 403;</code>。这一行 if 防<b>水平越权</b>(A 改 URL 里的 id 看 B 的数据)。列表查询也要带 userId 过滤，别查全表再前端筛。</p>\n    <p>垂直越权=普通用户调管理员接口→靠角色/权限注解(@PreAuthorize)或拦截器判角色。水平+垂直都要防。过关：跑通发码→注册→登录→带 Token 全链路+故意触发 401/403/400、能画注册与带 Token 流转图、能说出哈希/Redis/JWT/权限各解决什么。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>登录态≠数据归属；一行 if 防水平越权；角色判垂直越权；列表也要带 userId 过滤。</div>\n    <div class=\"recap\"><b>收束：</b>水平越权 if+垂直越权角色+列表过滤+401/403/400 故意触发。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：明文裸奔 vs 门锁齐备、门禁攻击沙盒</h2>\n    <p>演练一看「明文密码+无 Token+无权限」和「哈希+JWT+权限」的差别。演练二勾选四个防护（验证码过期/密码哈希/Token 验签/数据权限 if），看三种攻击（拖库/伪造 Token/偷看 B）能否成功。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种账号</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"naked\" class=\"on\">❌ 明文裸奔</button><button data-k=\"locked\">✅ 门锁齐备</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个账号系统，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 门禁攻击沙盒</b><span class=\"hint\">勾选四个防护</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1ttl\" checked> 验证码过期+限流</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1hash\" checked> 密码 BCrypt 哈希</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1jwt\" checked> JWT 验签+验过期</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1own\" checked> 数据权限 if</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">攻击: 拖库看明文 / 伪造 Token / 改 id 偷看 B</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>明文拖库全泄露；无验签可伪造 Token；无 if 改 id 就看 B。四防护齐备三种攻击都被挡。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会装门锁。下一课把 AI 聊天变真、学流式与跨线程坑。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>Redis 验证码</td><td>临时门禁码</td><td>TTL+限流+用一次即废</td></tr>\n      <tr><td>密码哈希</td><td>只登记齿形</td><td>BCrypt 自带盐+慢</td></tr>\n      <tr><td>JWT</td><td>签名自包含卡</td><td>验签+验过期/无状态</td></tr>\n      <tr><td>拦截器</td><td>Controller 前挡人</td><td>没带/过期/签错 401</td></tr>\n      <tr><td>数据权限</td><td>只刷自己家门</td><td>一行 if 防水平越权</td></tr>\n      <tr><td>垂直越权</td><td>普通调管理员</td><td>角色/权限注解</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，键/命令为示例；沙盒为启发式判定。口径以初级 README 与第五篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第五篇-完成账号系统 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 过关标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://jwt.io/introduction\" target=\"_blank\" rel=\"noopener\">JWT Introduction</a> <span class=\"src\">— 令牌结构与验签</span></li>\n        <li><a href=\"https://redis.io/docs/latest/\" target=\"_blank\" rel=\"noopener\">Redis Docs</a> <span class=\"src\">— TTL/限流</span></li>\n        <li><a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html\" target=\"_blank\" rel=\"noopener\">OWASP Password Storage</a> <span class=\"src\">— 哈希/加盐</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://developer.mozilla.org/zh-CN/docs/Web/API/Server-sent_events\" target=\"_blank\" rel=\"noopener\">MDN SSE</a> <span class=\"src\">— B6 流式输出</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"门禁比喻"},{"id":"b","title":"Redis 验证码"},{"id":"c","title":"密码哈希"},{"id":"d","title":"JWT/拦截器"},{"id":"e","title":"数据权限"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var NAKED=\"// ❌ 明文裸奔\\n密码明文存库 → 拖库全泄露\\n无 Token → 任何人调任何接口\\n无数据权限 → 改 id 看别人\\n验证码不过期 → 可重放\\nMD5 无盐 → 彩虹表秒破\";\n  var LOCKED=\"// ✅ 门锁齐备\\nRedis 验证码 TTL+限流+用一次即废\\nBCrypt 哈希(自带盐+慢) 存库\\n登录发 JWT, 拦截器验签+验过期\\n数据权限 if: 只准看自己的\\nHTTPS 传输防窃听\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"naked\"?NAKED:LOCKED);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"naked\"?\"err\":\"ok\")+\"\\\">\"+(k===\"naked\"?\"拖库/伪造/越权全通\":\"三种攻击都被挡\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"naked\"?\"物业抄了钥匙原件还不限门\":\"只登记齿形+卡只刷自己家\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"naked\");\n})();\n\n// 演练二：门禁攻击沙盒\n(function(){\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var ttl=chk('g1ttl'), hash=chk('g1hash'), jwt=chk('g1jwt'), own=chk('g1own');\n    var leak = !hash;          // 拖库看明文\n    var forge = !jwt;          // 伪造 Token\n    var peek = !own;           // 偷看 B\n    var blocked = [hash,jwt,own].filter(Boolean).length;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(leak?'bad':'good')+'\"><b>'+(leak?'泄露':'安全')+'</b><small>拖库</small></div>'+\n      '<div class=\"stat-box '+(forge?'bad':'good')+'\"><b>'+(forge?'可伪造':'挡回')+'</b><small>伪造Token</small></div>'+\n      '<div class=\"stat-box '+(peek?'bad':'good')+'\"><b>'+(peek?'可偷看':'403')+'</b><small>偷看B</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(ttl?'on':'bad')+'\">验证码 '+(ttl?'过期+限流':'可重放')+'</span>'+\n      '<span class=\"chip '+(hash?'on':'bad')+'\">哈希 '+(hash?'BCrypt':'明文')+'</span>'+\n      '<span class=\"chip '+(jwt?'on':'bad')+'\">验签 '+(jwt?'有':'无')+'</span>'+\n      '<span class=\"chip '+(own?'on':'bad')+'\">权限if '+(own?'有':'无')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">攻防</span>拖库:'+ (leak?'明文全泄露!':'只见哈希, 不可逆。')+' 伪造Token:'+ (forge?'无验签可伪造!':'签错/过期 401。')+' 偷看B:'+ (peek?'无 if 改 id 就看!':'归属不符 403。')+' 已挡 '+blocked+'/3 种核心攻击。';\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">TTL='+ttl+' 哈希='+hash+' 验签='+jwt+' 权限='+own+'</span></div>',\n      '<div><span class=\"'+(leak?'err':'ok')+'\">拖库 → '+(leak?'明文泄露':'哈希安全')+'</span></div>',\n      '<div><span class=\"'+(forge?'err':'ok')+'\">伪造Token → '+(forge?'成功':'401')+'</span></div>',\n      '<div><span class=\"'+(peek?'err':'ok')+'\">偷看B → '+(peek?'成功':'403')+'</span></div>'\n    ].join('');\n  }\n  ['g1ttl','g1hash','g1jwt','g1own'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 密码应存？\",\"opts\":[[\"BCrypt 哈希(自带盐+慢)\",true,\"对。不可逆。\"],[\"明文\",false,\"拖库全泄露。\"],[\"MD5 无盐\",false,\"彩虹表秒破。\"]]},{\"q\":\"2. 验证码放 Redis 因为？\",\"opts\":[[\"临时 TTL+共享+快+限流\",true,\"对。多实例共用。\"],[\"永久保存\",false,\"临时凭证。\"],[\"比 MySQL 便宜\",false,\"不是主因。\"]]},{\"q\":\"3. JWT payload 加密吗？\",\"opts\":[[\"不加密, 只 Base64+签名\",true,\"对。别放敏感信息。\"],[\"加密的\",false,\"仅编码。\"],[\"不可读\",false,\"可解码。\"]]},{\"q\":\"4. 拦截器作用位置？\",\"opts\":[[\"Controller 之前验 Token 挡人\",true,\"对。没带/过期 401。\"],[\"Controller 之后\",false,\"那就晚了。\"],[\"数据库里\",false,\"无关。\"]]},{\"q\":\"5. 防用户 A 改 id 看 B 靠？\",\"opts\":[[\"数据权限 if 校验归属\",true,\"对。水平越权。\"],[\"只验登录态\",false,\"登录≠归属。\"],[\"前端隐藏按钮\",false,\"可绕过。\"]]},{\"q\":\"6. 登录时比对？\",\"opts\":[[\"输入哈希后与库中哈希比\",true,\"对。不比明文。\"],[\"明文与明文比\",false,\"库不应有明文。\"],[\"盐与盐比\",false,\"比哈希。\"]]}];" },
    "backend|java|AI 聊天变真：SSE 与跨线程坑": { "body": "<p class=\"lead\">把「假的」AI 聊天变真：调真实模型 API、带历史消息保持上下文、SSE 逐字流式输出、补全会话管理；再看懂两个几乎所有新手都踩的坑——@Async 自调用静默失效、ThreadLocal 一换线程就没了。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">变真</span><span class=\"s\">调模型/带历史</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">流式</span><span class=\"s\">SSE 边挤边递</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">避坑</span><span class=\"s\">@Async/ThreadLocal</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>同一杯酸奶：整杯倒好 vs 边挤边递</h2>\n    <p>先讲个故事。同样一杯酸奶，可以等整杯倒好一次递给你，也可以边挤边递你边接边吃——东西一样，体验完全不同。AI 聊天就是后者：模型一个字一个字生成，服务端一块一块推给页面(<span class=\"term\">SSE</span>)。普通做法等菜全炒好再端上桌，客人干等；流式炒一口递一口。</p>\n    <p>第五篇的「AI 聊天」是假的：客户端永远返回固定文案、不记得上一句。本课变真：调真实模型 API、携带<span class=\"term2\">历史消息 List</span> 保持上下文、支持流式逐字、补会话列表/重命名/删除/历史查询。接入免费模型，不配 Key 自动降级模拟回复——不会「没 Key 就学不下去」。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>流式=边生成边推(SSE)；上下文=带历史 List 而非单字符串；没 Key 降级模拟保证可跑。</div>\n    <div class=\"recap\"><b>收束：</b>酸奶比喻+假变真+历史 List+免费/降级+会话管理。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>SSE 流式：服务端一块一块推，前端边收边渲染</h2>\n    <p><span class=\"term\">SSE</span>(Server-Sent Events)=服务端单向持续推文本流：响应 Content-Type: text/event-stream，连接保持打开，服务端 write 一块 flush 一块，前端 EventSource/fetch 流式读、边收边追加渲染。模型每生成一段就推一段，首字延迟从「等全文」降到「等第一段」。</p>\n    <p>Spring 里用 SseEmitter 或 ResponseBodyEmitter/Flux：Controller 返回 emitter，异步线程往里 send；完成 complete、出错 completeWithError。普通请求与流式请求在 Service 里<b>走不同路径</b>：普通=等全文一次性返回 JSON；流式=边生成边 send。分岔点就在「是否 stream=true」。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"普通响应 vs SSE 流式\">\n        <rect x=\"8\" y=\"26\" width=\"350\" height=\"60\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"183\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">普通: 整杯倒好</text><text x=\"183\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">等全文生成 → 一次 JSON 返回</text>\n        <rect x=\"402\" y=\"26\" width=\"350\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"577\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">SSE: 边挤边递</text><text x=\"577\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">生成一块推一块 → 边收边渲染</text>\n        <rect x=\"8\" y=\"106\" width=\"350\" height=\"44\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"183\" y=\"132\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#5B4A2F\">首字延迟 = 等全文(慢)</text>\n        <rect x=\"402\" y=\"106\" width=\"350\" height=\"44\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"577\" y=\"132\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#5B4A2F\">首字延迟 = 等第一段(快)</text>\n      </svg>\n      <figcaption>图 1 · 普通等整杯、SSE 边挤边递；菜一样体验不同。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>SSE=text/event-stream 持续推；SseEmitter 异步 send；普通/流式在 Service 分岔(stream 开关)。</div>\n    <div class=\"recap\"><b>收束：</b>SSE 原理+Content-Type+SseEmitter+分岔点+首字延迟。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>上下文与会话管理：带历史 List，别只传一句</h2>\n    <p>模型本身无状态，「记得上一句」靠客户端每次把<span class=\"term2\">历史消息 List&lt;ChatMessage&gt;</span>(role+content)一起传。所以 AIModelClient 参数是 List 而非单字符串。历史存哪？服务端会话表/Redis；注意<b>别无限增长</b>：截断窗口/摘要压缩，否则 token 爆+成本涨(呼应高级 A9)。</p>\n    <p>会话管理=真实聊天应用必备：会话列表、重命名、删除、历史消息查询。每个会话归属用户(数据权限 if，呼应 B5)。删除会话级联删消息；列表带 userId 过滤。 graduation 标准里网关版要求「调用日志可查询且不保存用户完整会话内容」——隐私与成本权衡。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>上下文=每次带历史 List；历史要截断/摘要防 token 爆；会话归属用户+级联删+列表过滤。</div>\n    <div class=\"recap\"><b>收束：</b>List 参数+历史截断+会话 CRUD+归属权限+隐私权衡。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>陷阱一：@Async 自调用为什么静默失效</h2>\n    <p><span class=\"term\">@Async</span> 靠 Spring <b>代理</b>生效：外部调 bean 的方法走代理→代理开新线程执行。但<b>同类内部</b> this.method() 自调用不走代理→@Async 静默失效，仍在原线程同步跑。新手看到「加了 @Async 怎么还是阻塞」就是这个。</p>\n    <p>解法：把异步方法拆到<b>另一个 bean</b>(如 ChatStreamWorker 单独类)注入调用；或自注入代理/ApplicationContext 取代理再调。这就是为什么 ChatStreamWorker 要单独拆成一个类——不是风格偏好，是<b>让代理生效</b>。同理 @Transactional 自调用也失效(B4 已提)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>@Async/@Transactional 靠代理；同类自调用不走代理=静默失效；拆到别的 bean 调用。</div>\n    <div class=\"recap\"><b>收束：</b>代理机制+自调用失效+拆 bean/自注入+ChatStreamWorker 拆类原因。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>陷阱二：ThreadLocal 一换线程就没了</h2>\n    <p><span class=\"term2\">ThreadLocal</span>=每个线程自己的「小本子」：拦截器把 userId 放进当前请求线程的 ThreadLocal，Service 随手取。但<b>换线程</b>(@Async/线程池/SSE 异步 send)后，新线程的小本子是空的→取到 null→「用户信息没了」。</p>\n    <p>解法：跨线程前<b>显式传递</b>上下文(把 userId 当参数传给异步任务)，或用 InheritableThreadLocal(仅父→子新建线程有效,线程池复用无效)、或 TransmittableThreadLocal(阿里,池化传递)。最稳=显式参数。记住：ThreadLocal 绑定线程不绑定任务；池化线程复用还会<b>串号</b>(上个任务残留)，用完必须 remove。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>ThreadLocal 绑线程不绑任务；换线程=小本子空；跨线程显式传参；池化用完 remove 防串号。</div>\n    <div class=\"recap\"><b>收束：</b>ThreadLocal 原理+换线程丢失+显式传参/ITL/TTL+remove 防串号。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：整杯 vs 边挤、流式与跨线程沙盒</h2>\n    <p>演练一看「等整杯倒好」和「边挤边递」的差别。演练二拖生成字数、切换 SSE/普通、切换「跨线程直接取 ThreadLocal」，看首字延迟与用户信息是否丢失。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种递法</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"whole\" class=\"on\">❌ 整杯倒好</button><button data-k=\"sse\">✅ 边挤边递</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一杯酸奶，两种体验</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 流式与跨线程沙盒</b><span class=\"hint\">拖字数+切开关</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>生成字数</label><input type=\"range\" id=\"g1len\" min=\"50\" max=\"2000\" value=\"800\"><span class=\"val\" id=\"g1lenV\">800</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sse\" checked> SSE 流式</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1tl\"> 跨线程直接取 ThreadLocal</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">首字延迟: 流式≈第一段 / 普通≈全文；跨线程取 ThreadLocal=null</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>字数越多普通首字越慢、流式首字恒定快；跨线程直接取 ThreadLocal 必丢用户信息，应显式传参。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会流式与避跨线程坑。下一课把项目变成能交付。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>SSE</td><td>边挤边递</td><td>text/event-stream 持续推</td></tr>\n      <tr><td>SseEmitter</td><td>异步往里 send</td><td>complete/completeWithError</td></tr>\n      <tr><td>上下文</td><td>带历史 List</td><td>截断/摘要防 token 爆</td></tr>\n      <tr><td>@Async 自调用</td><td>不走代理静默失效</td><td>拆到别的 bean</td></tr>\n      <tr><td>ThreadLocal</td><td>线程小本子</td><td>换线程空/显式传参/remove</td></tr>\n      <tr><td>降级</td><td>没 Key 模拟回复</td><td>保证可跑可学</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，延迟为量级示意；沙盒为模拟推导。口径以初级 README 与第六篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第六篇-完成AI聊天 <span class=\"src\">— 本课重写底稿(SSE/模型调用/异常仍可用)</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 网关改写方向与毕业标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://developer.mozilla.org/zh-CN/docs/Web/API/Server-sent_events\" target=\"_blank\" rel=\"noopener\">MDN SSE</a> <span class=\"src\">— 流式协议</span></li>\n        <li><a href=\"https://docs.spring.io/spring-framework/reference/integration/scheduling.html\" target=\"_blank\" rel=\"noopener\">Spring @Async</a> <span class=\"src\">— 代理与自调用</span></li>\n        <li><a href=\"https://platform.openai.com/docs/api-reference/streaming\" target=\"_blank\" rel=\"noopener\">OpenAI Streaming</a> <span class=\"src\">— 模型流式 API</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://docs.docker.com/get-started/\" target=\"_blank\" rel=\"noopener\">Docker Get Started</a> <span class=\"src\">— B7 交付打包</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"酸奶比喻"},{"id":"b","title":"SSE 流式"},{"id":"c","title":"上下文/会话"},{"id":"d","title":"@Async 自调用"},{"id":"e","title":"ThreadLocal"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var WHOLE=\"// ❌ 整杯倒好(普通响应)\\n等模型全文生成完\\n一次 JSON 返回\\n首字延迟 = 等全文(字数越多越慢)\\n客人干等, 以为卡死了\";\n  var SSE=\"// ✅ 边挤边递(SSE)\\nContent-Type: text/event-stream\\nSseEmitter 异步 send 一块 flush 一块\\n前端边收边追加渲染\\n首字延迟 = 等第一段(恒定快)\\n完成 complete / 出错 completeWithError\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"whole\"?WHOLE:SSE);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"whole\"?\"err\":\"ok\")+\"\\\">\"+(k===\"whole\"?\"首字=等全文, 干等\":\"首字=等第一段, 边收边看\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"whole\"?\"等菜全炒好再端\":\"炒一口递一口\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"whole\");\n})();\n\n// 演练二：流式与跨线程沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var len=val('g1len'); document.getElementById('g1lenV').textContent=len;\n    var sse=chk('g1sse'), tl=chk('g1tl');\n    var firstMs = sse? 300 : len*2;      // 流式首段恒定; 普通=全文\n    var lost = tl;                        // 跨线程直接取 ThreadLocal → null\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(sse?'good':'bad')+'\"><b>'+firstMs+'</b><small>首字延迟(ms)</small></div>'+\n      '<div class=\"stat-box\"><b>'+len+'</b><small>生成字数</small></div>'+\n      '<div class=\"stat-box '+(lost?'bad':'good')+'\"><b>'+(lost?'null':'有')+'</b><small>异步线程用户信息</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(sse?'on':'bad')+'\">'+(sse?'SSE 流式':'普通整杯')+'</span>'+\n      '<span class=\"chip '+(lost?'bad':'on')+'\">'+(lost?'跨线程取ThreadLocal=丢':'显式传参=有')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>首字延迟='+ (sse?'流式≈300ms(等第一段), 与字数无关。':'普通≈'+firstMs+'ms(等全文), 字数越多越慢。')+(lost?' 跨线程直接取 ThreadLocal → 新线程小本子空 → userId=null! 应显式传参。':' 跨线程显式传 userId → 异步任务拿得到。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">字数='+len+' SSE='+sse+' 跨线程取TL='+tl+'</span></div>',\n      '<div><span class=\"'+(sse?'ok':'err')+'\">首字延迟='+firstMs+'ms</span></div>',\n      '<div><span class=\"'+(lost?'err':'ok')+'\">异步用户信息='+(lost?'null(丢失)':'有(显式传参)')+'</span></div>',\n      '<div><span class=\"c\">// ThreadLocal 绑线程不绑任务; 换线程显式传参</span></div>'\n    ].join('');\n  }\n  document.getElementById('g1len').addEventListener('input',calc);\n  ['g1sse','g1tl'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. SSE 的响应 Content-Type？\",\"opts\":[[\"text/event-stream\",true,\"对。持续推文本流。\"],[\"application/json\",false,\"那是普通。\"],[\"text/html\",false,\"那是页面。\"]]},{\"q\":\"2. 模型「记得上一句」靠？\",\"opts\":[[\"客户端每次带历史 List\",true,\"对。模型无状态。\"],[\"模型自己存记忆\",false,\"无状态。\"],[\"只传当前一句\",false,\"接不上。\"]]},{\"q\":\"3. @Async 同类自调用会？\",\"opts\":[[\"静默失效(不走代理)\",true,\"对。拆到别的 bean。\"],[\"正常异步\",false,\"不走代理。\"],[\"报错\",false,\"静默不报。\"]]},{\"q\":\"4. ChatStreamWorker 单独拆类因为？\",\"opts\":[[\"让 @Async 代理生效\",true,\"对。非风格偏好。\"],[\"代码好看\",false,\"是机制需要。\"],[\"减少内存\",false,\"无关。\"]]},{\"q\":\"5. 换线程后 ThreadLocal 取到？\",\"opts\":[[\"null(新线程小本子空)\",true,\"对。应显式传参。\"],[\"原值\",false,\"绑线程不绑任务。\"],[\"自动继承\",false,\"池化复用不继承。\"]]},{\"q\":\"6. 线程池用完 ThreadLocal 必须？\",\"opts\":[[\"remove 防串号\",true,\"对。复用残留。\"],[\"不用管\",false,\"会串号。\"],[\"加密\",false,\"无关。\"]]}];" },
    "backend|java|能交付：测试、日志、文档与 Docker": { "body": "<p class=\"lead\">不学新框架，只做一件事：把「在我电脑上是好的」变成「谁拿到都能跑」。跟着小林同事翻车现场，补上测试、结构化日志、API 文档、Docker 四样，每样治一种病。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">翻车</span><span class=\"s\">只有我知道</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">四样</span><span class=\"s\">测试/日志/文档/Docker</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">上线</span><span class=\"s\">Nginx/HTTPS</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>小林翻车现场：代码没错，但只有他一个人知道</h2>\n    <p>先讲个故事。小林把项目发给同事「你跑一下看看」，同事花了一上午没跑起来：小林 JDK21 同事 JDK8；小林 MySQL8.0 同事 5.7；小林手动点过一百次都对同事机器翻车；小林说「密码错了」同事说「我填对了」吵二十分钟。小林每句话都没错——<b>问题在于这些东西只有小林一个人知道</b>。</p>\n    <p>「在我电脑上明明是好的啊」就是能跑和能交付之间那道鸿沟。同事一句话点醒：「你的东西只有你自己知道怎么跑，这不叫交付。」于是补四样：测试(改代码怕改坏)、结构化日志(出问题查不到)、API 文档(接口没人懂)、Docker(换机器就翻车)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>能跑≠能交付；把「只有我知道」写进项目里，别人才接得住。</div>\n    <div class=\"recap\"><b>收束：</b>翻车四现场+鸿沟=只有我知道+四样各治一种病。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>测试与结构化日志：改不坏、查得到</h2>\n    <p><b>自动化测试</b>治「改一行怕弄坏别处」：单元测试(JUnit5+Mockito)测 Service 逻辑、集成测试(@SpringBootTest+Testcontainers)测真实库/Redis。每次改代码跑一遍，绿了才敢提交；别靠手动点一百次。测试是<b>可重复的质检</b>，把手动经验固化成代码。</p>\n    <p><b>结构化日志</b>治「密码错了说不清」：用 JSON/键值日志带 traceId/userId/事件/结果/耗时，而非一句 System.out。登录失败记「原因=验证码过期/密码错/账号封」+traceId，用户报障给 traceId 一查就知。日志分级(DEBUG/INFO/WARN/ERROR)、别记敏感明文(密码/完整会话)。ELK/Loki 集中检索。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"交付四样各治一种病\">\n        <rect x=\"8\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"93\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">自动化测试</text><text x=\"93\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">治: 改代码怕改坏</text>\n        <rect x=\"200\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"285\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">结构化日志</text><text x=\"285\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">治: 出问题查不到</text>\n        <rect x=\"392\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"477\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">API 文档</text><text x=\"477\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">治: 接口没人懂</text>\n        <rect x=\"584\" y=\"26\" width=\"168\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"668\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">Docker 打包</text><text x=\"668\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">治: 换机器就翻车</text>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">把版本/步骤/约定/排错线索写进项目, 别人才接得住</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">测试=可重复质检 / 日志=traceId 一查就知 / 文档=自动生成 / Docker=一个盒子到哪都一样</text>\n      </svg>\n      <figcaption>图 1 · 四样东西各治小林翻车现场的一种病。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>测试=可重复质检别手动点；日志=结构化+traceId+原因分级，别记敏感明文。</div>\n    <div class=\"recap\"><b>收束：</b>单元/集成测试+绿了才提交+结构化日志 traceId/原因+分级+脱敏。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>API 文档与 Docker：接口有人懂、换机器不翻车</h2>\n    <p><b>API 文档</b>治「前端问你有啥接口难道手写 Word」：用 SpringDoc/OpenAPI 注解自动生成 Swagger UI，接口/参数/响应/错误码在线可试。文档随代码生成不滞后；约定统一响应 Result 与错误码表写进文档。</p>\n    <p><b>Docker</b>治「换机器翻车」：把应用+JDK+依赖+配置打成一个<span class=\"term\">镜像</span>，到哪台机器 <code>docker run</code> 都是同样东西。Dockerfile 多阶段构建(编译层+运行层)减小体积；docker-compose 一键拉起 app+MySQL+Redis+ Nginx。版本/环境写进镜像和 compose，不再口头交代。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>文档=OpenAPI 自动生成随代码不滞后；Docker=一个盒子到哪都一样，compose 一键拉齐中间件。</div>\n    <div class=\"recap\"><b>收束：</b>SpringDoc/Swagger+错误码表+镜像多阶段+compose 拉齐+环境写进项目。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>上线：Nginx 反向代理 + HTTPS</h2>\n    <p>交付最后一步上线：<span class=\"term\">Nginx</span> 做反向代理(对外 80/443→内部 app 8080)、静态资源、负载均衡、限流；<span class=\"term2\">HTTPS</span> 用 TLS 证书(Let's Encrypt 免费)加密传输防窃听/篡改(呼应 B5 密码传输)。配置 server_name/ssl_certificate/proxy_pass，HTTP 强制跳 HTTPS。</p>\n    <p>上线 checklist：镜像能跑、compose 拉齐、Nginx 代理通、HTTPS 生效、健康检查端点(/actuator/health)绿、日志集中、备份策略。毕业标准之一：服务能通过 Docker+Nginx+HTTPS 部署上线、能用日志定位一次模型调用失败。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Nginx 反向代理+HTTPS 加密+健康检查+日志集中+备份=上线 checklist。</div>\n    <div class=\"recap\"><b>收束：</b>Nginx 代理/静态/限流+TLS 证书+强制 HTTPS+health+上线 checklist。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>让 AI 补齐四样，但你要能验收</h2>\n    <p>四样都可以让 AI 帮写(测试用例/日志切面/OpenAPI 注解/Dockerfile)，但<b>你要能验收</b>：测试是否真覆盖边界(空/错/越权)、日志是否带 traceId 且脱敏、文档是否与代码一致、镜像是否真能在干净机器跑。AI 产出纳入证据闭环(呼应高级 A10)：不相信「我写完了」，只认可重复运行结果。</p>\n    <p>交付物=别人能独立跑起来+出错能自己查的包：README(版本/步骤/约定)+test.http/测试+Swagger+Dockerfile/compose+Nginx/HTTPS 配置+日志说明。把「只有我知道」全部写进项目，才算从能跑到能交付。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>AI 可补四样但你要验收(覆盖/脱敏/一致/干净机器能跑)；交付物=别人能独立跑+能自查的包。</div>\n    <div class=\"recap\"><b>收束：</b>AI 补齐+人验收四检查+交付物清单+写进项目。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：能跑 vs 能交付、交付四样沙盒</h2>\n    <p>演练一看「只有我知道」和「写进项目」的差别。演练二勾选四样（测试/日志/文档/Docker）+拖环境差异数，看同事能否独立跑、排错要多久。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种交付</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"mine\" class=\"on\">❌ 只有我知道</button><button data-k=\"pack\">✅ 写进项目</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个项目，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 交付四样沙盒</b><span class=\"hint\">勾四样+拖差异</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1test\" checked> 自动化测试</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1log\" checked> 结构化日志</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1doc\" checked> API 文档</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1docker\" checked> Docker 打包</label></div>\n        <div class=\"ctl\"><label>环境差异数</label><input type=\"range\" id=\"g1diff\" min=\"0\" max=\"5\" value=\"3\"><span class=\"val\" id=\"g1diffV\">3</span></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">Docker 抹平环境差异；日志决定排错时间；测试决定改不坏</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>无 Docker 时环境差异直接翻车；无日志排错靠猜(小时级)；有日志 traceId 分钟级；四样齐=同事独立跑+自查。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经能把能跑变能交付。下一课看清进阶路线。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>能跑vs能交付</td><td>只有我知道vs写进项目</td><td>鸿沟=口头经验</td></tr>\n      <tr><td>自动化测试</td><td>可重复质检</td><td>单元/集成, 绿了才提交</td></tr>\n      <tr><td>结构化日志</td><td>traceId 一查就知</td><td>键值/分级/脱敏</td></tr>\n      <tr><td>API 文档</td><td>自动生成不滞后</td><td>SpringDoc/Swagger</td></tr>\n      <tr><td>Docker</td><td>一个盒子到哪都一样</td><td>镜像多阶段/compose</td></tr>\n      <tr><td>Nginx/HTTPS</td><td>反向代理+加密</td><td>TLS/强制跳/health</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，排错时间为场景示意；沙盒为模拟推导。口径以初级 README 与第七篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第七篇-让项目可以交付 <span class=\"src\">— 本课重写底稿(小林故事)</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 毕业部署标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://docs.docker.com/get-started/\" target=\"_blank\" rel=\"noopener\">Docker Get Started</a> <span class=\"src\">— 镜像/compose</span></li>\n        <li><a href=\"https://swagger.io/specification/\" target=\"_blank\" rel=\"noopener\">OpenAPI Specification</a> <span class=\"src\">— 接口文档</span></li>\n        <li><a href=\"https://junit.org/junit5/docs/current/user-guide/\" target=\"_blank\" rel=\"noopener\">JUnit 5 User Guide</a> <span class=\"src\">— 自动化测试</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://martinfowler.com/bliki/MonolithFirst.html\" target=\"_blank\" rel=\"noopener\">Monolith First</a> <span class=\"src\">— B8/B9 单体与拆分边界</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"小林翻车"},{"id":"b","title":"测试/日志"},{"id":"c","title":"文档/Docker"},{"id":"d","title":"Nginx/HTTPS"},{"id":"e","title":"AI 补齐人验收"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var MINE=\"// ❌ 只有我知道\\nJDK/MySQL 版本口头交代\\n手动点一百次才算数\\n密码错了说不清(无日志)\\n接口靠手写 Word\\n换机器就翻车\\n同事一上午跑不起来\";\n  var PACK=\"// ✅ 写进项目\\n测试: 改代码跑一遍绿了才提交\\n日志: traceId+原因+分级+脱敏\\n文档: OpenAPI 自动生成在线可试\\nDocker: 镜像+compose 一键拉齐\\nNginx+HTTPS 上线\\n同事独立跑+出错自查\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"mine\"?MINE:PACK);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"mine\"?\"err\":\"ok\")+\"\\\">\"+(k===\"mine\"?\"同事跑不起来+扯皮\":\"别人接得住+能自查\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"mine\"?\"在我电脑上明明是好的\":\"把只有我知道写进项目\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"mine\");\n})();\n\n// 演练二：交付四样沙盒\n(function(){\n  function chk(id){return document.getElementById(id).checked;}\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var test=chk('g1test'), log=chk('g1log'), doc=chk('g1doc'), docker=chk('g1docker'), diff=val('g1diff');\n    document.getElementById('g1diffV').textContent=diff;\n    var runs = docker? true : (diff===0);      // 无 Docker 且环境有差异 → 翻车\n    var debugMin = log? 5 : 120;               // 有日志 traceId 分钟级 / 无靠猜小时级\n    var have=[test,log,doc,docker].filter(Boolean).length;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(runs?'good':'bad')+'\"><b>'+(runs?'能跑':'翻车')+'</b><small>同事独立跑</small></div>'+\n      '<div class=\"stat-box '+(log?'good':'bad')+'\"><b>'+debugMin+'</b><small>排错(min)</small></div>'+\n      '<div class=\"stat-box\"><b>'+have+'/4</b><small>四样齐备</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(test?'on':'bad')+'\">测试 '+(test?'有':'无')+'</span>'+\n      '<span class=\"chip '+(log?'on':'bad')+'\">日志 '+(log?'有':'无')+'</span>'+\n      '<span class=\"chip '+(doc?'on':'bad')+'\">文档 '+(doc?'有':'无')+'</span>'+\n      '<span class=\"chip '+(docker?'on':'bad')+'\">Docker '+(docker?'有':'无')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>'+(docker?'Docker 抹平 '+diff+' 项环境差异 → 同事能跑。':(diff===0?'环境无差异勉强能跑, 但换机器仍险。':'无 Docker + '+diff+' 项环境差异 → 同事翻车!'))+(log?' 日志 traceId → 排错 '+debugMin+'min。':' 无日志靠猜 → 排错 '+debugMin+'min。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">测试='+test+' 日志='+log+' 文档='+doc+' Docker='+docker+' 差异='+diff+'</span></div>',\n      '<div><span class=\"'+(runs?'ok':'err')+'\">同事独立跑 = '+(runs?'能':'翻车')+'</span></div>',\n      '<div><span class=\"'+(log?'ok':'err')+'\">排错 = '+debugMin+' min</span></div>',\n      '<div><span class=\"c\">// 能跑≠能交付; 四样把只有我知道写进项目</span></div>'\n    ].join('');\n  }\n  ['g1test','g1log','g1doc','g1docker'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  document.getElementById('g1diff').addEventListener('input',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 能跑和能交付的鸿沟是？\",\"opts\":[[\"只有我知道 vs 写进项目\",true,\"对。口头经验不算交付。\"],[\"代码行数\",false,\"无关。\"],[\"功能多少\",false,\"功能对也可能交付不了。\"]]},{\"q\":\"2. 治「改代码怕改坏」靠？\",\"opts\":[[\"自动化测试\",true,\"对。可重复质检。\"],[\"手动点一百次\",false,\"不可重复。\"],[\"不改动\",false,\"逃避。\"]]},{\"q\":\"3. 用户报障给 traceId 能？\",\"opts\":[[\"一查日志定位原因\",true,\"对。结构化日志价值。\"],[\"重置密码\",false,\"无关。\"],[\"加快网络\",false,\"无关。\"]]},{\"q\":\"4. 治「换机器翻车」靠？\",\"opts\":[[\"Docker 镜像+compose\",true,\"对。一个盒子到哪都一样。\"],[\"口头交代版本\",false,\"翻车源头。\"],[\"换同事机器\",false,\"逃避。\"]]},{\"q\":\"5. API 文档推荐？\",\"opts\":[[\"OpenAPI/Swagger 自动生成\",true,\"对。随代码不滞后。\"],[\"手写 Word\",false,\"滞后且累。\"],[\"不写文档\",false,\"接口没人懂。\"]]},{\"q\":\"6. HTTPS 的作用？\",\"opts\":[[\"加密传输防窃听篡改\",true,\"对。TLS 证书。\"],[\"加快编译\",false,\"无关。\"],[\"替代登录\",false,\"仍需认证。\"]]}];" },
    "backend|java|进阶路线：能跑、能扛、能负责": { "body": "<p class=\"lead\">不教新代码，给你一张路线图：初级项目是辆能开的原型车（几个人用/内网/重启就好），看清它在哪些场景抛锚（8 个缺口）、中级补什么才敢上高速、高级为什么完全不是同一件事。知道自己下一步学哪级、为什么。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">边界</span><span class=\"s\">能跑什么/扛不住什么</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">缺口</span><span class=\"s\">八个抛锚点</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">路线</span><span class=\"s\">中级能扛/高级能负责</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>老板问「能扛住吗」，小林愣住：不知道确认什么</h2>\n    <p>先讲个故事。小林把项目部署上线，公司几个人用得很开心。老板说「下周开放给全公司，你确认一下能扛住吗？」小林愣住——他不知道该确认什么。搜了一圈隐约知道「缓存、熔断、监控、CI/CD」这些词，但没人告诉他<b>自己的项目到底缺什么、缺了会怎样、什么时候该补</b>。</p>\n    <p>现在你手里是辆能开的原型车：几个人用、内网、出问题重启就好。它没毛病，只是还没上过高速。本课不教新代码，给你地图：把项目从头看一遍找出扛不住的地方，再告诉你这些缺口分别在中级/高级哪一篇补。看完再去第九篇毕业考。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>初级把功能做出来，中级让它在压力下不崩，高级决定该不该做并对结果负责。</div>\n    <div class=\"recap\"><b>收束：</b>原型车比喻+老板之问+缺口地图+三级定义。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>八个缺口：各自什么时候抛锚、哪个最致命</h2>\n    <p>把原型车从头看一遍，八个已知缺口：①<b>无缓存</b>(热点全打库,并发一高库先倒)②<b>无限流熔断</b>(一个慢依赖拖死全服务)③<b>无监控告警</b>(出事用户先知道)④<b>无 CI/CD</b>(发布靠手工,改坏直接上线)⑤<b>单点无冗余</b>(进程一挂全停)⑥<b>无压测</b>(不知道能扛多少)⑦<b>无灰度回滚</b>(新版全量翻车退不回)⑧<b>无容量规划</b>(流量来了临时抓瞎)。</p>\n    <p>哪个最致命？<b>无监控告警+无灰度回滚</b>组合最致命：出事不知道+知道了退不回。哪个可最后补？容量规划/多冗余在用户量小时可缓。判断顺序按「抛锚概率×影响面」，不是按名词热度。缺口不是缺陷清单，是<b>场景触发</b>：几个人用时都不抛锚，全公司开放就抛。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"三级要回答的问题越来越大\">\n        <rect x=\"8\" y=\"26\" width=\"230\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"123\" y=\"50\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">初级 · 能跑</text><text x=\"123\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">把功能做出来(原型车)</text>\n        <rect x=\"262\" y=\"26\" width=\"230\" height=\"60\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"377\" y=\"50\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">中级 · 能扛</text><text x=\"377\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">压力下不崩(上高速)</text>\n        <rect x=\"516\" y=\"26\" width=\"236\" height=\"60\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"634\" y=\"50\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">高级 · 能负责</text><text x=\"634\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">该不该做+对结果负责</text>\n        <rect x=\"8\" y=\"106\" width=\"744\" height=\"44\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"132\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">要回答的问题越来越大: 功能对不对 → 压力崩不崩 → 投资值不值/风险谁担</text>\n      </svg>\n      <figcaption>图 1 · 三级不是难度递增而是问题变大；高级不是「更难的中级」。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>八缺口按场景触发；最致命=无监控+无回滚组合；可缓=容量/冗余(量小时)；按概率×影响排序。</div>\n    <div class=\"recap\"><b>收束：</b>八缺口清单+场景触发+致命组合+排序原则。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>中级=能扛/能设计：十篇课对应你的缺口</h2>\n    <p>中级不是「更难的语法」，是<b>让原型车敢上高速</b>：缓存与 Redis 补①、幂等与韧性(限流熔断降级)补②、可观测与压测补③⑥、CI/CD 与交付补④⑦、消息队列与异步削峰、事务与一致性保数据、统一接入与路由/计量配额限流保多租户、六道关与模块设计让代码可演进。每一篇都对应你现在项目的一个具体缺口。</p>\n    <p>中级的思维转变：从「实现功能」到「<b>设计在压力下仍正确的系统</b>」——考虑并发/失败/部分成功/重试/回滚/容量。学中级时带着自己项目的缺口去学，每学一篇问「它补我哪个缺口、补完能扛什么」。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>中级=能扛/能设计；十篇各补一个缺口；带着自己项目的缺口学，问补完能扛什么。</div>\n    <div class=\"recap\"><b>收束：</b>缺口→中级篇映射+思维转变(压力下正确)+带缺口学。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>高级=能负责：完全不是同一件事</h2>\n    <p>高级不是「更难的中级」。中级问「怎么让系统不崩」，高级问「<b>该不该做、做到什么程度、谁对结果负责</b>」：战略(模糊需求→系统战略)、取舍(质量属性/ADR)、边界(领域/团队)、一致性决策、平台契约、弹性形态、SLO/容灾、安全/供应链、成本/FinOps、技术领导力。高级的产出是<b>决策与证据</b>而非代码量。</p>\n    <p>所以别用「刷更多中级题」准备高级。高级要练：面对模糊需求能澄清取舍、能写 ADR 说清备选与代价、能对投资/暂停/退出负责、能在条件突变时重算(呼应高级 A11)。判断自己该学哪级：若项目还没上压力→中级；若已能扛但要决定方向/边界/成本/责任→高级。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>高级=能负责(该不该做/谁担结果)，产出决策与证据；不是更难的中级；按「上压力没/要决策没」选级。</div>\n    <div class=\"recap\"><b>收束：</b>高级问题域+决策证据产出+别刷中级题准备高级+选级判据。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>知道自己站在哪、下一步往哪走</h2>\n    <p>路线自检三问：①我的项目现在能扛什么场景(几个人/内网/重启可恢复)？②开放到更大规模时哪个缺口先抛锚(按概率×影响)？③我下一步要「补扛压能力」(中级)还是「做方向/边界/成本决策」(高级)？答清三问就知道学哪级、为什么，而不是跟着名词热度走。</p>\n    <p>本课过关：能说出项目什么场景稳定/什么场景出问题、八缺口哪个最致命哪个可最后补、中级十篇与项目关系、判断自己适合哪级。然后去 B9 毕业考：把 JVM/线程池/MQ/微服务/网关串起来独立交付。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>路线自检三问(能扛什么/先抛哪个/补能力还是做决策)；答清才选级，不跟名词热度。</div>\n    <div class=\"recap\"><b>收束：</b>三问自检+过关四条+衔接 B9 毕业考。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：原型车 vs 高速、缺口抛锚沙盒</h2>\n    <p>演练一看「几个人内网重启就好」和「全公司开放」的差别。演练二拖并发人数+勾选缓存/熔断/监控，看是否抛锚、该补哪一级。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种路况</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"proto\" class=\"on\">❌ 原型车内网</button><button data-k=\"highway\">✅ 全公司高速</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一辆车，两种路况</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 缺口抛锚沙盒</b><span class=\"hint\">拖并发+勾防护</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>并发人数</label><input type=\"range\" id=\"g1n\" min=\"5\" max=\"2000\" value=\"200\"><span class=\"val\" id=\"g1nV\">200</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1cache\"> 缓存</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1break\"> 限流熔断</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1mon\"> 监控告警</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">缺口按场景触发: 量小不抛 / 量大抛；监控决定「知不知道」</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>5 人内网三防护全无也不抛；200 人无缓存库先倒、无熔断慢依赖拖死、无监控出事用户先知道。补防护=中级能力。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经知道自己站在哪、下一步往哪走。下一课毕业考串起来独立交付。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>三级</td><td>能跑/能扛/能负责</td><td>问题越来越大</td></tr>\n      <tr><td>八缺口</td><td>抛锚点</td><td>缓存/熔断/监控/CI/单点/压测/灰度/容量</td></tr>\n      <tr><td>最致命组合</td><td>不知道+退不回</td><td>无监控+无灰度回滚</td></tr>\n      <tr><td>中级</td><td>能扛/能设计</td><td>十篇各补一缺口</td></tr>\n      <tr><td>高级</td><td>能负责</td><td>决策与证据, 非更难中级</td></tr>\n      <tr><td>选级三问</td><td>能扛什么/先抛哪个/补能力or决策</td><td>不跟名词热度</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，并发阈值为场景示意；沙盒为启发式判定。口径以初级 README 与第八篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第八篇-从能跑通到能扛住-三级进阶路线 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 三级定位</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://martinfowler.com/bliki/MonolithFirst.html\" target=\"_blank\" rel=\"noopener\">Monolith First</a> <span class=\"src\">— 先单体后拆分的边界</span></li>\n        <li><a href=\"https://sre.google/sre-book/\" target=\"_blank\" rel=\"noopener\">Google SRE Book</a> <span class=\"src\">— 能扛/能负责的运行视角</span></li>\n        <li><a href=\"https://12factor.net/\" target=\"_blank\" rel=\"noopener\">The Twelve-Factor App</a> <span class=\"src\">— 可交付/可演进应用基线</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://dev.java/learn/jvm/\" target=\"_blank\" rel=\"noopener\">Dev.java JVM</a> <span class=\"src\">— B9 JVM/GC/线程池</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"老板之问"},{"id":"b","title":"八缺口"},{"id":"c","title":"中级能扛"},{"id":"d","title":"高级能负责"},{"id":"e","title":"选级三问"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var PROTO=\"// ❌ 原型车(几个人/内网)\\n无缓存/无熔断/无监控 也不抛锚\\n出问题重启就好\\n发布靠手工\\n不知道能扛多少\\n「能开」但没上过高速\";\n  var HIGH=\"// ✅ 上高速(全公司开放)\\n缓存: 热点不打库\\n限流熔断: 慢依赖不拖死全服务\\n监控告警: 出事先于用户知道\\nCI/CD+灰度回滚: 改坏退得回\\n压测+容量: 知道能扛多少\\n这些=中级要补的能力\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"proto\"?PROTO:HIGH);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"proto\"?\"err\":\"ok\")+\"\\\">\"+(k===\"proto\"?\"量小不抛≠能扛\":\"缺口按场景触发, 量大抛锚\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"proto\"?\"没上过高速\":\"补防护才敢上高速\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"proto\");\n})();\n\n// 演练二：缺口抛锚沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var n=val('g1n'); document.getElementById('g1nV').textContent=n;\n    var cache=chk('g1cache'), brk=chk('g1break'), mon=chk('g1mon');\n    var dbDown = (n>100)&&!cache;        // 量大无缓存库先倒\n    var drag = (n>100)&&!brk;            // 量大无熔断慢依赖拖死\n    var blind = !mon;                    // 无监控出事用户先知道\n    var anchor = dbDown||drag;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(anchor?'bad':'good')+'\"><b>'+(anchor?'抛锚':'稳定')+'</b><small>运行状态</small></div>'+\n      '<div class=\"stat-box '+(blind?'bad':'good')+'\"><b>'+(blind?'用户先知道':'告警先知道')+'</b><small>谁先发现</small></div>'+\n      '<div class=\"stat-box\"><b>'+n+'</b><small>并发人数</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(cache?'on':'bad')+'\">缓存 '+(cache?'有':'无')+'</span>'+\n      '<span class=\"chip '+(brk?'on':'bad')+'\">熔断 '+(brk?'有':'无')+'</span>'+\n      '<span class=\"chip '+(mon?'on':'bad')+'\">监控 '+(mon?'有':'无')+'</span>'+\n      '<span class=\"chip '+(dbDown?'bad':'')+'\">库 '+(dbDown?'先倒':'OK')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>并发 '+n+'：'+(n<=100?'量小, 三防护全无也暂不抛锚(原型车场景)。':(dbDown?'无缓存→热点全打库→库先倒! ':'')+(drag?'无熔断→慢依赖拖死全服务! ':'')+(!dbDown&&!drag?'防护齐→扛住。':''))+(blind?' 无监控→出事用户先知道(最致命组合之一)。':' 监控→告警先于用户。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">并发='+n+' 缓存='+cache+' 熔断='+brk+' 监控='+mon+'</span></div>',\n      '<div><span class=\"'+(anchor?'err':'ok')+'\">抛锚 = '+(anchor?'是':'否')+' (库倒='+dbDown+' 拖死='+drag+')</span></div>',\n      '<div><span class=\"'+(blind?'err':'ok')+'\">谁先发现 = '+(blind?'用户':'告警')+'</span></div>',\n      '<div><span class=\"c\">// 缺口按场景触发; 补防护=中级能力</span></div>'\n    ].join('');\n  }\n  document.getElementById('g1n').addEventListener('input',calc);\n  ['g1cache','g1break','g1mon'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 三级要回答的问题？\",\"opts\":[[\"功能对不对→压力崩不崩→该不该做/谁负责\",true,\"对。问题越来越大。\"],[\"语法难度递增\",false,\"不是难度递增。\"],[\"代码量递增\",false,\"无关。\"]]},{\"q\":\"2. 最致命的缺口组合？\",\"opts\":[[\"无监控+无灰度回滚\",true,\"对。不知道+退不回。\"],[\"无缓存+无压测\",false,\"严重但非最致命组合。\"],[\"无文档+无测试\",false,\"交付问题非运行致命。\"]]},{\"q\":\"3. 中级核心转变？\",\"opts\":[[\"从实现功能到设计压力下仍正确\",true,\"对。能扛/能设计。\"],[\"背更多语法\",false,\"不是。\"],[\"写更多代码\",false,\"不是量。\"]]},{\"q\":\"4. 高级是更难的中级吗？\",\"opts\":[[\"不是, 是能负责/做决策\",true,\"对。产出决策与证据。\"],[\"是\",false,\"问题域不同。\"],[\"只是更多框架\",false,\"不是。\"]]},{\"q\":\"5. 缺口什么时候抛锚？\",\"opts\":[[\"场景触发: 量大/开放时才抛\",true,\"对。几个人用不抛。\"],[\"永远抛锚\",false,\"量小不抛。\"],[\"与场景无关\",false,\"恰恰相关。\"]]},{\"q\":\"6. 选级应依据？\",\"opts\":[[\"项目上压力没/要做决策没\",true,\"对。三问自检。\"],[\"名词热度\",false,\"别跟热度。\"],[\"别人学啥我学啥\",false,\"按自己项目。\"]]}];" },
    "backend|java|毕业考：串起来独立交付": { "body": "<p class=\"lead\">毕业考不再给逐行答案：把前八篇串起来，面对一个场景自己判断「该用线程池还是消息队列」「这个规模要不要拆微服务」，最后用一次生产级配置证明你能独立交付 Spring Boot 后端。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">串起来</span><span class=\"s\">知识地图</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">JVM/线程池</span><span class=\"s\">内存与并发</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">MQ/微服务/网关</span><span class=\"s\">边界判断</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>凌晨两点被叫醒：Full GC 刷屏，老年代快满</h2>\n    <p>先讲个故事。小林上线第三天凌晨两点被叫醒：接口时不时卡十几秒。打开日志一堆 <b>Full GC</b>，监控老年代快满——第六篇塞进 Redis 的历史消息缓存，从来没人告诉 GC 哪些该删。产品又补一句：「下周全公司开放，200 人同时在线，你能扛住吗？」小林没配过线程池、没看过 JVM 参数、更不知 MQ 是什么。</p>\n    <p>毕业考就是让他从能跑到能扛：不是教新代码，而是逼你把前八篇连起来看——JVM、线程池、消息队列、微服务、AI 网关。这些不是考点，是上线前要过的心。<b>毕业不是背定义，是拿到场景能说清该用哪块知识、为什么。</b></p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>毕业=按场景取用知识并说清为什么；不是背定义；凌晨电话=缓存无界+无并发/容量规划的后果。</div>\n    <div class=\"recap\"><b>收束：</b>凌晨电话故事+Full GC 根因+串地图+毕业定义。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>JVM 内存与 GC：堆是公共桌面、栈是个人便签</h2>\n    <p><span class=\"term\">堆</span>=公共大桌面，谁都能放对象，所以要有人收拾(<span class=\"term2\">GC</span>)；<span class=\"term\">栈</span>=每个线程自己的便签本，方法帧用完就扔；<span class=\"term\">元空间</span>=放类元数据。老年代满→Full GC→Stop-The-World 卡顿。历史缓存无界增长=对象一直活着进老年代→GC 收不掉→OOM/卡顿。</p>\n    <p>对策：缓存设上限+TTL/淘汰(LRU)、别把大对象长生命周期持有、选合适 GC(G1 默认平衡)、设堆大小(-Xms/-Xmx 同值防抖动)、看 GC 日志定位。理解「堆/栈/元空间各管什么+GC 为什么收不掉活对象」才看得懂 OutOfMemoryError 与 Full GC 刷屏。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"JVM 内存与毕业知识地图\">\n        <rect x=\"8\" y=\"26\" width=\"230\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"123\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">堆(公共桌面)</text><text x=\"123\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">对象/GC 收拾/老年代</text>\n        <rect x=\"262\" y=\"26\" width=\"230\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"377\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">栈(个人便签)</text><text x=\"377\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">每线程方法帧/用完扔</text>\n        <rect x=\"516\" y=\"26\" width=\"236\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"634\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">元空间</text><text x=\"634\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">类元数据</text>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">毕业地图: JVM/GC → 线程池 → MQ 削峰 → 单体/微服务边界 → AI 网关</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">缓存无界→活对象进老年代→Full GC 收不掉→卡顿/OOM；设上限+TTL+淘汰</text>\n      </svg>\n      <figcaption>图 1 · 堆/栈/元空间各管什么；毕业把五块知识连成地图按场景取用。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>堆公共/栈个人/元空间类；GC 收不掉活对象；缓存无界=Full GC 根因；上限+TTL+淘汰+G1+堆同值。</div>\n    <div class=\"recap\"><b>收束：</b>三区职责+GC/STW+无界缓存根因+对策清单。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>线程池参数：core/max/队列/拒绝，按场景配</h2>\n    <p><span class=\"term\">线程池</span>四关键：<b>corePoolSize</b>(常驻线程)、<b>maximumPoolSize</b>(峰值上限)、<b>workQueue</b>(排队缓冲)、<b>拒绝策略</b>(满时怎么办)。任务来→core 未满建核心线程→core 满进队列→队列满建到 max→max 满触发拒绝。理解这条顺序才懂「为什么 core 满了不立刻加线程」(先排队)。</p>\n    <p>按场景配：CPU 密集≈核数+1；IO 密集(调模型/查库)≈核数×(1+等待/计算)或压测定；队列别用无界(LinkedBlockingQueue 默认 Integer.MAX=OOM 隐患,呼应凌晨电话)；拒绝策略按业务(调用方重试/降级/快速失败)。200 人在线的 SSE 长连接更要算线程/连接上限,别默认配置硬扛。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>core→队列→max→拒绝四步顺序；CPU≈核+1/IO 压测定；队列别有界防 OOM；拒绝按业务。</div>\n    <div class=\"recap\"><b>收束：</b>四参数+提交顺序+CPU/IO 经验+有界队列+拒绝策略+SSE 连接上限。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>MQ 与微服务边界：什么时候该上、什么时候不该拆</h2>\n    <p><span class=\"term2\">消息队列</span>核心价值=<b>削峰+解耦+异步</b>：瞬时洪峰先入队慢慢消费(削峰)、生产消费互不等待(解耦)、耗时操作后台做(异步)。什么时候上：写洪峰/跨系统通知/可接受最终一致。什么时候不上：强同步求立即结果/量小简单场景(加 MQ 反而增运维与一致性复杂度)。</p>\n    <p><b>微服务边界</b>：单体优先(MonolithFirst)——团队小/规模小/边界不清时拆微服务=分布式税(网络/一致性/运维/部署)远超收益。该拆的信号：团队大到沟通阻塞、模块需独立扩缩/独立发布、边界已清晰。200 人在线的初级项目<b>不该拆</b>：一个 Spring Boot 进程+缓存+线程池调优足够。判断「该不该」比「会不会拆」更重要。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>MQ=削峰/解耦/异步, 强同步/量小不上；微服务单体优先, 团队/扩缩/边界清晰才拆；200 人不该拆。</div>\n    <div class=\"recap\"><b>收束：</b>MQ 三价值+上/不上判据+MonolithFirst+拆的信号+200 人不拆。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>企业 AI 网关 + 生产级配置：独立交付的证明</h2>\n    <p>毕业项目=<b>企业 AI 网关</b>：/v1/models 与 /v1/chat/completions 可被第三方客户端调、普通+SSE 流式都正确转发、注册登录+创建 API 令牌、调用结束 Token/积分记录正确、余额不足/令牌禁用/模型停用返回明确错误、调用日志可查询且不存完整会话、Docker+Nginx+HTTPS 上线、能用日志定位一次调用失败。网关管：鉴权/路由/计量/限流/日志(呼应中高级)。</p>\n    <p>生产级配置判断(毕业答卷)：给 200 人在线场景→堆 -Xms=-Xmx+G1+缓存上限 TTL；线程池 IO 型有界队列+合理拒绝；SSE 连接上限+背压；不拆微服务；MQ 仅用于调用日志异步落库(削峰)；监控告警+灰度回滚+压测验证。<b>每项配置说清为什么</b>，才算独立交付而非抄配置。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>网关=鉴权/路由/计量/限流/日志+毕业八标准；生产配置每项说清为什么=独立交付证明。</div>\n    <div class=\"recap\"><b>收束：</b>网关职责+毕业八标准+200 人生产配置答卷+说清为什么。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：背定义 vs 按场景、生产配置沙盒</h2>\n    <p>演练一看「背定义」和「按场景取用并说清为什么」的差别。演练二拖在线人数+勾选线程池/GC/缓存/MQ 配置+切换「拆微服务」，看能否扛住与拆/不拆判断。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种毕业</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"recite\" class=\"on\">❌ 背定义</button><button data-k=\"apply\">✅ 按场景取用</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个毕业考，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 生产配置沙盒</b><span class=\"hint\">拖人数+勾配置+切拆</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>在线人数</label><input type=\"range\" id=\"g1n\" min=\"10\" max=\"2000\" value=\"200\"><span class=\"val\" id=\"g1nV\">200</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1pool\" checked> 线程池有界+合理拒绝</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1gc\" checked> GC/堆同值+缓存上限TTL</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1mq\"> MQ 异步落日志</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1split\"> 拆微服务</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">200 人: 单体+调优足够, 拆=分布式税；MQ 仅削峰落日志</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>背定义答不出「200 人该不该拆」；按场景能 say 清。无 GC/缓存上限→Full GC；无有界线程池→OOM；200 人拆微服务=负收益。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。恭喜初级毕业：你能按场景取用知识、说清为什么、独立交付生产级 Spring Boot 后端。接下来可进中级「能扛」。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>堆/栈/元空间</td><td>公共桌面/个人便签/类</td><td>GC 收活对象不了</td></tr>\n      <tr><td>Full GC 根因</td><td>缓存无界活对象</td><td>上限+TTL+淘汰</td></tr>\n      <tr><td>线程池四参</td><td>core/队列/max/拒绝</td><td>提交顺序+有界队列</td></tr>\n      <tr><td>MQ</td><td>削峰/解耦/异步</td><td>强同步/量小不上</td></tr>\n      <tr><td>微服务边界</td><td>单体优先</td><td>团队/扩缩/边界清晰才拆</td></tr>\n      <tr><td>AI 网关</td><td>鉴权/路由/计量/限流/日志</td><td>毕业八标准</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，人数/参数为场景示意；沙盒为启发式判定。口径以初级 README 与第九篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》初级工程师 · 第九篇-初级毕业考 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>初级工程师/README.md <span class=\"src\">— 毕业项目与八条毕业标准</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://dev.java/learn/jvm/\" target=\"_blank\" rel=\"noopener\">Dev.java JVM</a> <span class=\"src\">— 内存/GC</span></li>\n        <li><a href=\"https://docs.spring.io/spring-boot/reference/\" target=\"_blank\" rel=\"noopener\">Spring Boot Reference</a> <span class=\"src\">— 生产配置</span></li>\n        <li><a href=\"https://martinfowler.com/bliki/MonolithFirst.html\" target=\"_blank\" rel=\"noopener\">Monolith First</a> <span class=\"src\">— 拆分边界</span></li>\n      </ul>\n      <h3>课程完结 / 进阶</h3>\n      <ul>\n        <li>初级 B1–B9 能力链 <span class=\"src\">— 认识→Java→Web→Spring→账号→AI→交付→路线→毕业</span></li>\n        <li>中级「能扛」J1–J11 <span class=\"src\">— 下一步: 压力下不崩</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"凌晨电话"},{"id":"b","title":"JVM/GC"},{"id":"c","title":"线程池"},{"id":"d","title":"MQ/微服务"},{"id":"e","title":"网关/生产配置"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var RECITE=\"// ❌ 背定义\\n「堆是对象区栈是方法帧」\\n「MQ 是消息队列」\\n「微服务是拆分」\\n问: 200人该不该拆? → 答不出\\n问: 为什么 Full GC? → 只会背名词\\n配置靠抄, 不说为什么\";\n  var APPLY=\"// ✅ 按场景取用 + 说清为什么\\nFull GC → 缓存无界活对象 → 上限+TTL+G1\\n200人 → 单体+线程池有界+调优, 不拆\\nMQ → 仅异步落日志削峰, 强同步不上\\n每项配置说清为什么 = 独立交付\\n毕业不是背定义是场景判断\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"recite\"?RECITE:APPLY);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"recite\"?\"err\":\"ok\")+\"\\\">\"+(k===\"recite\"?\"答不出该不该/为什么\":\"按场景取用+说清为什么\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"recite\"?\"考点不是知识地图\":\"毕业=独立交付证明\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"recite\");\n})();\n\n// 演练二：生产配置沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var n=val('g1n'); document.getElementById('g1nV').textContent=n;\n    var pool=chk('g1pool'), gc=chk('g1gc'), mq=chk('g1mq'), split=chk('g1split');\n    var gcBad = !gc;                 // Full GC/OOM 风险\n    var poolBad = !pool;             // 无界队列/拒绝 OOM 风险\n    var hold = !gcBad && !poolBad;   // 扛住\n    var shouldSplit = n>1000;        // 启发: 超千人/多团队才考虑拆\n    var splitVerdict = split? (shouldSplit?'可考虑':'负收益(分布式税)') : (shouldSplit?'可评估拆':'正确(单体优先)');\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(hold?'good':'bad')+'\"><b>'+(hold?'扛住':'抛锚')+'</b><small>运行</small></div>'+\n      '<div class=\"stat-box '+(split===shouldSplit?'good':'bad')+'\"><b>'+(split?'拆':'单体')+'</b><small>当前选择</small></div>'+\n      '<div class=\"stat-box\"><b>'+n+'</b><small>在线人数</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(gc?'on':'bad')+'\">GC/缓存 '+(gc?'配好':'无界→FullGC')+'</span>'+\n      '<span class=\"chip '+(pool?'on':'bad')+'\">线程池 '+(pool?'有界':'无界→OOM')+'</span>'+\n      '<span class=\"chip '+(mq?'on':'')+'\">MQ '+(mq?'异步落日志':'未用')+'</span>'+\n      '<span class=\"chip '+(split===shouldSplit?'on':'bad')+'\">拆分判断 '+splitVerdict+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">答卷</span>'+n+' 人在线：'+(hold?'GC/缓存上限+有界线程池 → 扛住。':'配置缺口 → '+(gcBad?'Full GC/OOM ':'')+(poolBad?'线程池 OOM ':'')+'!')+' 拆分：'+(shouldSplit?'规模大, 可评估拆(需团队/边界清晰)。':'单体优先, 拆=分布式税负收益。')+(mq?' MQ 仅削峰异步落日志, 合理。':' 日志同步落库量大时可加 MQ 削峰。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">人数='+n+' 线程池='+pool+' GC='+gc+' MQ='+mq+' 拆='+split+'</span></div>',\n      '<div><span class=\"'+(hold?'ok':'err')+'\">扛住 = '+hold+'</span></div>',\n      '<div><span class=\"'+(split===shouldSplit?'ok':'err')+'\">拆分判断 = '+splitVerdict+'</span></div>',\n      '<div><span class=\"c\">// 每项配置说清为什么 = 独立交付</span></div>'\n    ].join('');\n  }\n  document.getElementById('g1n').addEventListener('input',calc);\n  ['g1pool','g1gc','g1mq','g1split'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 堆和栈的比喻？\",\"opts\":[[\"堆公共桌面/栈个人便签\",true,\"对。GC 收拾堆。\"],[\"堆个人/栈公共\",false,\"反了。\"],[\"都公共\",false,\"栈每线程私有。\"]]},{\"q\":\"2. Full GC 刷屏根因常是？\",\"opts\":[[\"缓存无界→活对象进老年代收不掉\",true,\"对。设上限+TTL。\"],[\"栈太深\",false,\"栈溢出另因。\"],[\"元空间满必 FullGC\",false,\"非此场景根因。\"]]},{\"q\":\"3. 线程池 core 满后先？\",\"opts\":[[\"进队列, 队列满才加到 max\",true,\"对。提交顺序。\"],[\"立刻加到 max\",false,\"先排队。\"],[\"直接拒绝\",false,\"max 满才拒绝。\"]]},{\"q\":\"4. 200 人在线初级项目该拆微服务吗？\",\"opts\":[[\"不该, 单体+调优足够\",true,\"对。MonolithFirst。\"],[\"该, 越拆越好\",false,\"分布式税。\"],[\"必须拆\",false,\"无依据。\"]]},{\"q\":\"5. MQ 核心价值？\",\"opts\":[[\"削峰+解耦+异步\",true,\"对。强同步/量小不上。\"],[\"加快 CPU\",false,\"无关。\"],[\"替代数据库\",false,\"不是。\"]]},{\"q\":\"6. 毕业的定义？\",\"opts\":[[\"按场景取用知识并说清为什么\",true,\"对。非背定义。\"],[\"背全所有定义\",false,\"不是。\"],[\"抄生产配置\",false,\"要说清为什么。\"]]}];" }
  };
  return { get: function (t, s, l) { var k = t + "|" + s + "|" + l; return data[k] || (prev ? prev.get(t, s, l) : null); } };
})(window.QZ_CONTENT);
